(function (root) {
  root.ASVAB_BANK = root.ASVAB_BANK || {};
  root.ASVAB_BANK["AR"] = [{"id": "AR-0001", "source_number": 1, "subtest": "AR", "stem": "If a car is towed 12 miles to the repair shop, and the tow charge is $3.50 per mile, how much did\nthe tow cost?", "options": {"A": "$12.00", "B": "$3.50", "C": "$42.00", "D": "$100.00"}, "answer": "C", "answer_raw": "C", "explanation": "Multiply 12 miles by $3.50 per mile to get $42.00.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 2, "flags": [], "page": 3, "excluded": false}, {"id": "AR-0002", "source_number": 2, "subtest": "AR", "stem": "The sum of two numbers is 70. One number is 8 more than the other.\nWhat's the smaller number?", "options": {"A": "31", "B": "33", "C": "35", "D": "36"}, "answer": "A", "answer_raw": "A", "explanation": "Let x = the smaller number and x + 8 equal the larger number. Because the sum of the two\nnumbers equals 70, you can express this mathematically as x + (x + 8) = 70. Now all you have\nto do is solve for x. Combine the like terms: 2x + 8 = 70. Then subtract 8 from both sides of the\nequation: 2x + 8 - 8 = 70 - 8, or 2x = 62. Divide both sides of the equation by two, and you find\nthat x is equal to 31.", "figure": null, "passage_id": null, "topics": ["ratio_proportion", "averages"], "difficulty": 2, "flags": [], "page": 3, "excluded": false}, {"id": "AR-0003", "source_number": 3, "subtest": "AR", "stem": "A sales manager buys antacid in bottles by the gross.\nIf he goes through 3 bottles of antacid every day, how long will the gross last?", "options": {"A": "144 days", "B": "3 days", "C": "20 days", "D": "48 days"}, "answer": "D", "answer_raw": "D", "explanation": "144 bottles are in a gross. 144 \u00f7 3 (bottles per day) = 48 days.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 1, "flags": [], "page": 3, "excluded": false}, {"id": "AR-0004", "source_number": 4, "subtest": "AR", "stem": "Jenny's test grades are 93, 89, 96, and 98.\nIf she wishes to raise her average to 95, what does she need to score on her next test?", "options": {"A": "100", "B": "99", "C": "97", "D": "95"}, "answer": "B", "answer_raw": "B", "explanation": "To determine Jenny's average, add the test scores and divide the sum by the number of tests\ntaken.\nYou want to know what she would need to make on the next test in order to achieve an average\nof 95.\nThe formula can be set up as (93 + 89 + 96 + 98 + x) \u00f7 5 = 95.\nCombining the like terms results in (376 + x) \u00f7 5 = 95.\nMultiplying both sides by 5 results in 376 + x = 475. So, x = 99.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "averages"], "difficulty": 3, "flags": [], "page": 4, "excluded": false}, {"id": "AR-0005", "source_number": 5, "subtest": "AR", "stem": "A waitress earns an average tip of 12% of the cost of the food she serves.\nIf she serves $375 worth of food in one evening, how much money in tips will she earn on\naverage?", "options": {"A": "$37", "B": "$45", "C": "$42", "D": "$420"}, "answer": "B", "answer_raw": "B", "explanation": "Multiply the total amount spent on drinks, $375, by 12% to determine the amount of tips. $375 \u00d7\n0.12 = $45.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "averages"], "difficulty": 1, "flags": [], "page": 4, "excluded": false}, {"id": "AR-0006", "source_number": 6, "subtest": "AR", "stem": "How many square feet of carpeting are needed to carpet a 12-foot \u00d7 12-foot room?", "options": {"A": "24", "B": "120", "C": "48", "D": "144"}, "answer": "D", "answer_raw": "D", "explanation": "Square footage is determined by multiplying length by width, or 12 \u00d7 12 = 144.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 2, "flags": [], "page": 4, "excluded": false}, {"id": "AR-0007", "source_number": 7, "subtest": "AR", "stem": "Carpet stain protector costs $0.65 per square yard to apply.\nHow much will it cost to apply the protectant to a 16-foot \u00d7 18-foot carpet?", "options": {"A": "$187.20", "B": "$62.40", "C": "$20.80", "D": "$96.00"}, "answer": "C", "answer_raw": "C", "explanation": "To determine the number of square yards to be protected, multiply 16 feet by 18 feet to\ndetermine the number of square feet, 288. Then divide 288 by 9 to convert square feet to\nsquare yards (1 square yard = 3 feet \u00d7 3 feet = 9 square feet). Multiply the quotient, 32 square\nyards, by the cost of protection per square yard, $0.65, to get the correct answer, $20.80.\nRemember to perform all the steps in a calculation.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "cost_profit"], "difficulty": 4, "flags": [], "page": 5, "excluded": false}, {"id": "AR-0008", "source_number": 8, "subtest": "AR", "stem": "A printing plant that produces baseball cards has a monthly overhead of $6,000. It costs 18\ncents to print each card, and the cards sell for 30 cents each.\nHow many cards must the printing plant sell each month in order to make a profit?", "options": {"A": "30,000", "B": "40,000", "C": "50,000", "D": "60,000"}, "answer": "C", "answer_raw": "C", "explanation": "Let x = the number of cards printed and sold each month. Therefore, cost is equal to 6000 +\n18x, and revenue is equal to 0.30x. You're looking for the point where revenue is greater than\nthe cost (revenue > cost). The inequity is 0.30x > 6000 + 18x. Subtracting 18x from both sides\nof the inequity results in 0.12x > 6000. Divide both sides by 0.12. The result is that x > 50,000.\nThe printing plant would have to print and sell 50,000 cards per month to make a profit.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": [], "page": 5, "excluded": false}, {"id": "AR-0009", "source_number": 9, "subtest": "AR", "stem": "Joe received an hourly wage of $8.15. His boss gave him a 7% raise.\nHow much does Joe make per hour now?", "options": {"A": "$0.57", "B": "$8.90", "C": "$8.72", "D": "$13.85"}, "answer": "C", "answer_raw": "C", "explanation": "To calculate the new wage, start off by multiplying $8.15 \u00d7 0.07 = $0.57. Then add that number\n(the amount of Joe's raise) to his original hourly wage. Joe's new hourly wage is $8.15 + $0.57\n= $8.72.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "work_rate", "rate_time_distance"], "difficulty": 3, "flags": [], "page": 5, "excluded": false}, {"id": "AR-0010", "source_number": 10, "subtest": "AR", "stem": "Alice leaves her house, driving east at 45 miles per hour (mph). Thirty minutes later, her\nhusband Dave notices she forgot her cell phone and sets off after her.\nHow fast must Dave travel in order to catch up with Alice 3 hours after he leaves?", "options": {"A": "49 mph", "B": "50.5 mph", "C": "52.5 mph", "D": "54 mph"}, "answer": "C", "answer_raw": "C", "explanation": "By the time Dave leaves, Alice has already been traveling for half an hour. Three hours later,\nshe would've been traveling for 31/2 hours at 45 mph, or 157.5 miles. In order to travel 157.5\nmiles in 3 hours, Dave would have to travel at 52.5 mph (divide 157.5 by 3).", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 4, "flags": [], "page": 6, "excluded": false}, {"id": "AR-0011", "source_number": 11, "subtest": "AR", "stem": "A baker made 20 pies. A Boy Scout troop buys one-fourth of his pies, a preschool teacher buys\none-third of his pies, and a caterer buys one-sixth of his pies.\nHow many pies does the baker have left?", "options": {"A": "3/4", "B": "15", "C": "12", "D": "5"}, "answer": "D", "answer_raw": "D", "explanation": "Convert the different denominators to a common denominator that all the denominators can\ndivide into evenly.\n4, 3, and 6 all divide evenly into 12.\nTo convert 1/4 to x/12, divide 12 (the new common denominator) by 4 (the old common\ndenominator) to get 3.\nThen multiply 1/4 by 3/3 (another way of saying 1).\nDo the same calculation for the other fractions: 1/3 = 4/12 and 1/6 = 2/12.\nThen add the new numerators together: 3 + 4 + 2 = 9.\nThis gives you your new added numerator.\nPlace the added numerator over the new denominator, and you can see that 9/12 of the pies\nhave been sold.\n9/12 can be reduced to 3/4.\n3/4 or 75% of the pies have been sold.\n\n\n\n20 \u00d7 0.75 = 15.\n15 of 20 pies have been sold.\n20 - 15 = 5 pies remaining", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 5, "flags": [], "page": 6, "excluded": false}, {"id": "AR-0012", "source_number": 12, "subtest": "AR", "stem": "Miriam bought five cases of motor oil on sale. A case of motor oil normally costs $24.00, but she\nwas able to purchase the oil for $22.50 a case.\nHow much money did Miriam save on her entire purchase?", "options": {"A": "$7.50", "B": "$1.50", "C": "$8.00", "D": "$22.50"}, "answer": "A", "answer_raw": "A", "explanation": "Subtract the sale price from the regular price: $24.00 - $22.50 = $1.50. Multiply the remainder\nby the number of cases to get your $1.50 \u00d7 5 = $7.50.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 7, "excluded": false}, {"id": "AR-0013", "source_number": 13, "subtest": "AR", "stem": "A security guard walks the equivalent of six city blocks when he makes a circuit around the\nbuilding.\nIf he walks at a pace of eight city blocks every 30 minutes, how long will it take him to complete\na circuit around the building, assuming he doesn't run into any thieves?", "options": {"A": "20.00 minutes", "B": "3.75 minutes", "C": "22.50 minutes", "D": "24.00 minutes"}, "answer": "C", "answer_raw": "C", "explanation": "Divide 30 by 8 to determine that the security guard takes 3.75 minutes to walk one city block.\nMultiply 3.75 by 6, the number of blocks it takes to complete the circuit, to arrive at 22.50, or\n221/2 minutes.", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 2, "flags": [], "page": 7, "excluded": false}, {"id": "AR-0014", "source_number": 14, "subtest": "AR", "stem": "The population of Grand Island, Nebraska, grew by 600,000 people between 1995 and 2005,\none-fifth more than the town council predicted.\nThe town council originally predicted the city's population would grow by __________.", "options": {"A": "400,000", "B": "500,000", "C": "300,000", "D": "200,000"}, "answer": "B", "answer_raw": "B", "explanation": "Let x = the original estimate. An additional one-fifth would be 6/5x, or 120% of x.\nThe equation can be expressed as 1.2x = 600000.\nTo solve for x, divide both sides of the equation by 1.2.\nx = 500,000.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 3, "flags": [], "page": 7, "excluded": false}, {"id": "AR-0015", "source_number": 15, "subtest": "AR", "stem": "Joan is taking an admissions examination.\nIf she has to get at least 40 of the 60 questions right to pass, what percent of the questions does\nshe need to answer correctly?", "options": {"A": "30%", "B": "40%", "C": "661/3%", "D": "662/3%"}, "answer": "D", "answer_raw": "D", "explanation": "Divide the number of questions she must get right (40) by the total number of questions (60) to\nreach 662/3%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 8, "excluded": false}, {"id": "AR-0016", "source_number": 16, "subtest": "AR", "stem": "A teacher deposited $3,000 in a retirement fund.\nIf she didn't add any more money to the fund, which earns an annual interest rate of 6%, how\nmuch money would she have in 1 year?", "options": {"A": "$180", "B": "$3,006", "C": "$3,180", "D": "$6,000"}, "answer": "C", "answer_raw": "C", "explanation": "To determine the amount of interest earned, multiply the principal ($3,000) by the interest rate\n(6%) and the number of years interest accrues (1 year): $3,000 \u00d7 0.06 \u00d7 1 = $180.\nAdd the interest earned to the principal to show how much total money the teacher would have:\n$180 + $3,000 = $3,180.", "figure": null, "passage_id": null, "topics": ["simple_interest", "percentages_discount"], "difficulty": 3, "flags": [], "page": 8, "excluded": false}, {"id": "AR-0017", "source_number": 17, "subtest": "AR", "stem": "The high-school track measures one quarter of a mile around.\nHow many laps would you have to run in order to run three and a half miles?", "options": {"A": "12", "B": "14", "C": "16", "D": "18"}, "answer": "B", "answer_raw": "B", "explanation": "Divide the total number of laps by the length of one lap. 31/2 \u00f7 1/4. First, convert the mixed\nnumber to a fraction, then divide by 1/4.\n7/2 \u00f7 1/4 = 28/2, which can be reduced to 14.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 1, "flags": [], "page": 8, "excluded": false}, {"id": "AR-0018", "source_number": 18, "subtest": "AR", "stem": "Karl is driving in Austria, where the speed limit is posted in kilometers per hour. The car's\nspeedometer shows that he's traveling at a rate of 75 kilometers per hour. Karl knows that a\nkilometer is about 5/8 of a mile.\nApproximately how many miles per hour is Karl traveling?", "options": {"A": "47", "B": "120", "C": "50", "D": "53"}, "answer": "A", "answer_raw": "A", "explanation": "A kilometer is 5/8 of a mile, so multiply 75 \u00d7 5/8, or 75/1 \u00d7 5/8 = 375/8.\nDivide 8 into 375 to reduce the fraction and determine that Karl was traveling at 47 miles per\nhour.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 4, "flags": [], "page": 9, "excluded": false}, {"id": "AR-0019", "source_number": 19, "subtest": "AR", "stem": "A carpenter earns $12.30 an hour for a 40-hour week. His overtime pay is 11/2 times his base\npay.\nIf he puts in a 46-hour week, how much is his weekly pay?", "options": {"A": "$602.70", "B": "$492.00", "C": "$565.80", "D": "$110.70"}, "answer": "A", "answer_raw": "A", "explanation": "$12.30 \u00d7 40 hours = $492, his base pay per week. $12.30 \u00d7 1.5 = $18.45, his overtime rate per\nhour. $18.45 (overtime rate per hour) \u00d7 6 (hours of overtime) = $110.70 (overtime pay). $492.00\n(base pay) + $110.70 (overtime pay) = $602.70 (total pay for the week).", "figure": null, "passage_id": null, "topics": ["work_rate"], "difficulty": 5, "flags": [], "page": 9, "excluded": false}, {"id": "AR-0020", "source_number": 20, "subtest": "AR", "stem": "An office building has 30 employees and allows 42 square feet of work space per employee.\nIf five more employees are hired, how much less work space wills each employee have?", "options": {"A": "6 square feet", "B": "7 square feet", "C": "7.5 square feet", "D": "8 square feet"}, "answer": "A", "answer_raw": "A", "explanation": "The office has 1,260 square feet of space (multiply 42 square feet by 30 employees). With 35\nemployees, each employee will have 36 square feet of work space (1,260 \u00f7 35), which is 6\nsquare feet less than originally.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "ratio_proportion"], "difficulty": 2, "flags": [], "page": 9, "excluded": false}, {"id": "AR-0021", "source_number": 21, "subtest": "AR", "stem": "Stan bought a monster truck for $2,000 down and payments of $450 a month for five years.\nWhat's the total cost of the monster truck?", "options": {"A": "$4,250", "B": "$29,000", "C": "$27,000", "D": "$34,400"}, "answer": "B", "answer_raw": "B", "explanation": "Five years contain 60 months, so multiply $450 (monthly payment) \u00d7 60 = $27,000 (total\npayments). Then add $27,000 (total payments) + $2,000 (down payment) = $29,000 (total cost).", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": [], "page": 10, "excluded": false}, {"id": "AR-0022", "source_number": 22, "subtest": "AR", "stem": "Darla spent $120.37 on groceries in January, $108.45 in February, and $114.86 in March.\nWhat was the average monthly cost of Darla's groceries?", "options": {"A": "$343.68", "B": "$110.45", "C": "$114.86", "D": "$114.56"}, "answer": "D", "answer_raw": "D", "explanation": "Add the three monthly amounts to determine the total amount Darla spent on groceries: $120.37\n+ $108.45 + $114.86 = $343.68.\nDivide the total by 3 to determine the average monthly cost: $114.56.", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 2, "flags": [], "page": 10, "excluded": false}, {"id": "AR-0023", "source_number": 23, "subtest": "AR", "stem": "Keith is driving from Reno to Kansas City to meet his girlfriend. The distance between the two\ncities is 1,650\nmiles.\n\n\n\nIf Keith can average 50 miles per hour, how many hours will it take him to complete his trip?", "options": {"A": "8 hours", "B": "30 hours", "C": "33 hours", "D": "82 hours"}, "answer": "C", "answer_raw": "C", "explanation": "1,650 miles (total distance) \u00f7 50 miles per hour (average speed) = 33 hours.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate", "averages"], "difficulty": 4, "flags": [], "page": 10, "excluded": false}, {"id": "AR-0024", "source_number": 24, "subtest": "AR", "stem": "Michael needs 55 gallons of paint to paint an apartment building. He would like to purchase the\npaint for the least amount of money possible.\nWhich of the following should he buy?", "options": {"A": "two 25-gallon buckets at $550 each", "B": "eleven 5-gallon buckets at $108 each", "C": "six 10-gallon buckets at $215 each", "D": "fifty-five 1-gallon buckets at $23 each"}, "answer": "B", "answer_raw": "B", "explanation": "Determine the cost of each option.\nChoice (two 25-gallon buckets at $550 each): doesn't provide enough paint (2 \u00d7 25 gallons = 50\ngallons).\nChoice (eleven 5-gallon buckets at $108 each): 11 \u00d7 $108 = $1,188.\nChoice (six 10-gallon buckets at $215 each): 6 \u00d7 $215 = $1,290.\nChoice (fifty-five 1-gallon buckets at $23 each): 55 \u00d7 $23 = $1,265.\nThe lowest price is $1,188.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 11, "excluded": false}, {"id": "AR-0025", "source_number": 25, "subtest": "AR", "stem": "As a member of FEMA, you're required to set up a contingency plan to supply meals to\nresidents of a town devastated by a tornado. A breakfast ration weighs 12 ounces and the lunch\nand dinner rations weigh 18 ounces each.\nAssuming a food truck can carry 3 tons and that each resident will receive 3 meals per day, how\nmany residents can you feed from one truck during a 10-day period?", "options": {"A": "150 residents", "B": "200 residents", "C": "250 residents", "D": "300 residents"}, "answer": "B", "answer_raw": "B", "explanation": "One ton = 2,000 pounds, so one truck can carry 6,000 pounds.\n\n\n\nThere are 16 ounces in a pound, so one truck can carry 96,000 ounces.\nThe total daily ration for each resident is 12 ounces + 18 ounces + 18 ounces, or 48 ounces.\nThe number of daily rations supplied can be expressed as 96,000 \u00f7 48 = 2,000.\nDividing 2,000 by 10 days results in 200 residents who can be fed by one truck during this 10-\nday period.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 5, "flags": [], "page": 11, "excluded": false}, {"id": "AR-0026", "source_number": 26, "subtest": "AR", "stem": "A train headed south for Wichita left the station at the same time a train headed north for Des\nMoines left the same station. The train headed for Wichita traveled at 55 miles per hour. The\ntrain headed for Des Moines traveled at 70 miles per hour.\nHow many miles apart were the trains at the end of 3 hours?", "options": {"A": "210 miles", "B": "165 miles", "C": "125 miles", "D": "375 miles"}, "answer": "D", "answer_raw": "D", "explanation": "The train headed for Wichita traveled 55 miles per hour \u00d7 3 hours = 165 total miles. The train\nheaded for Des Moines traveled 70 miles per hour \u00d7 3 hours = 210 total miles. Adding the\ndistances together gives you the number of miles apart the two trains were after three hours:\n210 + 165 = 375. Another option: You can add the two rates of speed (55 + 70) and multiply the\nsum by 3 hours (125 \u00d7 3 hours = 375).", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 5, "flags": [], "page": 12, "excluded": false}, {"id": "AR-0027", "source_number": 27, "subtest": "AR", "stem": "A carpenter needs to cut four sections, each 3-feet 8-inches long, from a piece of molding.\nIf the board is only sold by the foot, what's the shortest length of board she can buy?", "options": {"A": "15 feet", "B": "14 feet", "C": "16 feet", "D": "12 feet"}, "answer": "A", "answer_raw": "A", "explanation": "Convert the mixed number to inches. 3 feet 8 inches equals 44 inches (12 inches per foot \u00d7 3\nfeet = 36 inches + 8 inches = 44 inches). 44 inches (length each section needs to be) \u00d7 4\n(number of sections needed) = 176 inches (total molding needed). To determine the amount of\nmolding needed in feet, convert 176 inches into feet by dividing 176 inches by 12 inches. You\nget 142/3 feet, so the shortest board length is 15 feet.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 12, "excluded": false}, {"id": "AR-0028", "source_number": 28, "subtest": "AR", "stem": "Kiya had a coupon for 10% off one frozen turkey breast. The turkey breasts cost $8.50 each,\nand Kiya bought two.\nHow much did she pay?", "options": {"A": "$16.15", "B": "$17.00", "C": "$15.30", "D": "$7.65"}, "answer": "A", "answer_raw": "A", "explanation": "One turkey breast costs $8.50 minus 10% of $8.50, or $8.50 - $0.85 = $7.65. The other turkey\nbreast is full price. $7.65 + $8.50 = $16.15.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 12, "excluded": false}, {"id": "AR-0029", "source_number": 29, "subtest": "AR", "stem": "A recruiter travels 1,100 miles during a 40-hour workweek.\nIf she spends 2/5 of her time traveling, how many hours does she spend traveling?", "options": {"A": "22", "B": "51/2", "C": "16", "D": "8"}, "answer": "C", "answer_raw": "C", "explanation": "Don't let the number of miles traveled confuse you - you don't use them to solve the problem.\n2/5 of a 40-hour workweek is 2/5 \u00d7 40/1 = 80/5. Reduce the fraction: 80 \u00f7 5 = 16 hours per\nweek spent traveling.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 3, "flags": [], "page": 13, "excluded": false}, {"id": "AR-0030", "source_number": 30, "subtest": "AR", "stem": "Your car uses gasoline at the rate of 21 miles per gallon.\nIf gasoline costs $2.82 per gallon, and you drive for 7 hours at a speed of 48 miles per hour,\nhow much will you pay for gasoline for the trip?", "options": {"A": "$38.18", "B": "$45.12", "C": "$47.73", "D": "$59.27"}, "answer": "B", "answer_raw": "B", "explanation": "Your first step is to determine the number of miles traveled. Multiply the rate of travel by the\ntime. 48x \u00d7 7 = 336 miles. The amount of gas used is the total miles driven, divided by the\nnumber of miles per gallon. 336 \u00f7 21 = 16 gallons of gasoline used. At the price of $2.82 per\ngallon, you spent $45.12 for gas ($2.82x \u00d7 16 = $45.12).", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate", "unit_conversion"], "difficulty": 4, "flags": [], "page": 13, "excluded": false}, {"id": "AR-0031", "source_number": 31, "subtest": "AR", "stem": "If a hexahedral die is rolled two times, what's the probability of NOT rolling a five both times?", "options": {"A": "1/36", "B": "1/6", "C": "4/36", "D": "25/36"}, "answer": "D", "answer_raw": "D", "explanation": "The probability of rolling a 5 is 1 out of 6 (1/6), so the probability of NOT rolling a 5 is 1 - 1/6, or\n5/6. The probability of not rolling a 5 twice is 5/6 \u00d7 5/6, or 25/36.", "figure": null, "passage_id": null, "topics": ["basic_probability"], "difficulty": 1, "flags": [], "page": 13, "excluded": false}, {"id": "AR-0032", "source_number": 32, "subtest": "AR", "stem": "Jack loaned Bob $1,500 at an annual interest rate of 7%.\nAfter one year, how much will Bob owe Jack?", "options": {"A": "$105", "B": "$1,500", "C": "$1,605", "D": "$1,507"}, "answer": "C", "answer_raw": "C", "explanation": "Multiply loaned money, $1,500, by 7% to determine how much is the annual interest rate.\n$1,500 \u00d7 0.07 = $105.\nThen add the annual interest state to the total amount of debt $105 + $1,500 = $1,605.", "figure": null, "passage_id": null, "topics": ["simple_interest", "percentages_discount"], "difficulty": 3, "flags": [], "page": 14, "excluded": false}, {"id": "AR-0033", "source_number": 33, "subtest": "AR", "stem": "A 2-ton truck is taxed at a rate of $0.12 per pound.\nHow much is the total tax bill?", "options": {"A": "$480", "B": "$240", "C": "$120", "D": "$600"}, "answer": "A", "answer_raw": "A", "explanation": "2 tons = 4,000 pounds. 4,000 \u00d7 $0.12 = $480.00.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 14, "excluded": false}, {"id": "AR-0034", "source_number": 34, "subtest": "AR", "stem": "If ab = 10, and a2 + b2 = 30, solve for y in the equation, y = (a + b)2.", "options": {"A": "40", "B": "45", "C": "50", "D": "55"}, "answer": "C", "answer_raw": "C", "explanation": "y = (a + b)2. Expanding the equation results in y = a2 + b2 + 2ab. You know that a2 + b2 = 30,\nand ab = 10. When you substitute these known values into the equation, you get y = 30 + 2(10).\nSolving for y, results in y = 50.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 14, "excluded": false}, {"id": "AR-0035", "source_number": 35, "subtest": "AR", "stem": "A half-pint of cream is what part of a gallon?", "options": {"A": "1/8", "B": "1/4", "C": "1/16", "D": "1/6"}, "answer": "C", "answer_raw": "C", "explanation": "8 pints make up a gallon, so a gallon contains 16 half-pints. One half-pint equals 1/16 of a\ngallon.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 15, "excluded": false}, {"id": "AR-0036", "source_number": 36, "subtest": "AR", "stem": "The cost of a protein bar increased from $2.50 to $2.80.\nHow much was the percent increase to the $2.80 rate?", "options": {"A": "16%", "B": "10%", "C": "15%", "D": "12%"}, "answer": "D", "answer_raw": "D", "explanation": "First subtract the old cost from the new cost: $2.80 - $2.50 = $0.30. Then divide the difference\nby the old cost to find the percent difference: $0.30 \u00f7 $2.50 = 0.12 = 12%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 15, "excluded": false}, {"id": "AR-0037", "source_number": 37, "subtest": "AR", "stem": "An aircraft flies over Boondock Air Force Base at 10:20 a.m. At 10:32 a.m., the plane passes\nover Sea Side Naval Air Station, 120 miles away.\nHow fast is the aircraft traveling?", "options": {"A": "400 mph", "B": "500 mph", "C": "600 mph", "D": "700 mph"}, "answer": "C", "answer_raw": "C", "explanation": "The aircraft travels 120 miles in 12 minutes, which is 1/5 of an hour. Therefore, in 5/5 (one)\nhour, it would travel 5 \u00d7 120, or 600 miles. The aircraft is traveling 600 miles per hour.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 3, "flags": [], "page": 15, "excluded": false}, {"id": "AR-0038", "source_number": 38, "subtest": "AR", "stem": "Last year, Margot grew 50 bushels of corn in her backyard. This year, the yield has increased\n8%.\nHow many bushels of corn did Margot grow this year?", "options": {"A": "56", "B": "52", "C": "60", "D": "54"}, "answer": "D", "answer_raw": "D", "explanation": "Multiply 50 bushels by 8% to find the yield increase in bushels: 50 \u00d7 0.08 = 4. Add 4 bushels\n(the amount of the increase) to 50 bushels (the original yield) to determine that an 8% increase\nequals 54 bushels.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 16, "excluded": false}, {"id": "AR-0039", "source_number": 39, "subtest": "AR", "stem": "Junior has saved money in his piggybank over the winter. He wants to buy a $30 computer\ngame.\nIf he has 14 one-dollar bills, 16 half dollars, 12 quarters, 8 dimes, 25 nickels, and 10 pennies,\nhow much more does he need to borrow from Dad to buy the game?", "options": {"A": "$27.15", "B": "$2.85", "C": "$2.95", "D": "$1.85"}, "answer": "B", "answer_raw": "B", "explanation": "Convert the change to dollars or fractions of dollars and add:\n\n\n\n\nSubtract the total from $30.00 to determine how much money Junior has to borrow:\n$30.00 - $27.15 = $2.85.", "figure": "assets/figures/q0039.jpg", "passage_id": null, "topics": ["cost_profit"], "difficulty": 5, "flags": ["tag_fallback", "has_figure"], "page": 16, "excluded": false}, {"id": "AR-0040", "source_number": 40, "subtest": "AR", "stem": "Debbie receives a weekly salary of $80, plus a 5% commission on any sales. During the week,\nshe has $800 in total sales.\nWhat's the ratio of her commission to her salary?", "options": {"A": "2/1", "B": "1/2", "C": "3/1", "D": "1/3"}, "answer": "B", "answer_raw": "B", "explanation": "Her commission for the week was $40 (0.05 \u00d7 800 = 40). The ratio of her commission to her\nsalary is 40/80, which can be reduced to 1/2.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "ratio_proportion"], "difficulty": 3, "flags": [], "page": 17, "excluded": false}, {"id": "AR-0041", "source_number": 41, "subtest": "AR", "stem": "How many quart cans can be filled from a 25-gallon bucket of paint?", "options": {"A": "50", "B": "75", "C": "100", "D": "80"}, "answer": "C", "answer_raw": "C", "explanation": "A gallon consists of 4 quarts. 4 \u00d7 25 = 100.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 17, "excluded": false}, {"id": "AR-0042", "source_number": 42, "subtest": "AR", "stem": "If a crew of four people can paint the barn in three days, how long will it take a crew of two\npeople?", "options": {"A": "4 days", "B": "11/2 days", "C": "8 days", "D": "6 days"}, "answer": "D", "answer_raw": "D", "explanation": "Dividing 4 crewmembers by 2 crewmembers shows that 4 members are twice as many as 2\nmembers. Multiply the number of days it would take 4 people to paint by 2 (3 \u00d7 2) to determine\nhow long it would take 2 people to do the same task.", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 1, "flags": [], "page": 18, "excluded": false}, {"id": "AR-0043", "source_number": 43, "subtest": "AR", "stem": "Brian works for five hours and is paid $24. Christina works for three hours and is paid $10.95.\nHow much more per hour does Brian make than Christina?", "options": {"A": "$1.15", "B": "$1.25", "C": "$1.35", "D": "$1.37"}, "answer": "A", "answer_raw": "A", "explanation": "Brian's hourly wage is 24/5 ($4.80). Christina's hourly wage is 10.95/3 ($3.65).\n$4.80 - $3.65 = $1.15.", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 3, "flags": [], "page": 18, "excluded": false}, {"id": "AR-0044", "source_number": 44, "subtest": "AR", "stem": "Margaret is getting married and must be ready by 11:15 a.m. If it's now 8:30 a.m., how much\ntime does she have to get ready?", "options": {"A": "11/2 hours", "B": "21/2 hours", "C": "23/4 hours", "D": "21/3 hours"}, "answer": "C", "answer_raw": "C", "explanation": "The amount of time from 8:30 a.m. to 11:15 a.m. is 2 hours and 45 minutes, or 245/60. To\n\n\n\nreduce the fraction, divide 45 by 60 to get 0.75, or 3/4. The total amount of time Margaret has to\nget ready is 23/4 hours.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 3, "flags": [], "page": 18, "excluded": false}, {"id": "AR-0045", "source_number": 45, "subtest": "AR", "stem": "An accounting-firm employee is asked to shred 900 documents.\nIf he can shred documents at a rate of 7 per minute, the number of documents remaining after\n11/2 hours of shredding is __________.", "options": {"A": "630", "B": "90", "C": "270", "D": "810"}, "answer": "C", "answer_raw": "C", "explanation": "At a rate of 7 documents per minute, the employee can shred 630 documents in 90 minutes.\nHow do you come up with that number? Multiply 7 by 90 (the number of minutes in 11/2 hours).\nSubtract 630 from 900 total documents to determine that after 11/2 hours of shredding, 270\ndocuments remain.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 4, "flags": [], "page": 19, "excluded": false}, {"id": "AR-0046", "source_number": 46, "subtest": "AR", "stem": "A home stereo depreciates by 20% each year.\nWhat's the value of a stereo, purchased new for $1,200, after two years?", "options": {"A": "$768", "B": "$693", "C": "$827", "D": "$654"}, "answer": "A", "answer_raw": "A", "explanation": "The stereo depreciates $240 the first year (0.2 \u00d7 1200 = 240). Therefore, the value of the stereo\nafter the first year is $1200 - $240 = $960. The second year the stereo would depreciate by\n$192 (0.2 \u00d7 960). The value of the stereo after the second year is $960 - $192 = $768.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 19, "excluded": false}, {"id": "AR-0047", "source_number": 47, "subtest": "AR", "stem": "Janet's old pickup truck can only reach a speed of 45 miles per hour.\nIf she drives at top speed, how long will it take her to reach a city 135 miles away?", "options": {"A": "3 hours", "B": "2 hours", "C": "4 hours", "D": "21/2 hours"}, "answer": "A", "answer_raw": "A", "explanation": "Divide the distance (135 miles) by the speed (45 miles per hour) to determine that Janet will\ntake 3 hours to reach the city.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 3, "flags": [], "page": 19, "excluded": false}, {"id": "AR-0048", "source_number": 48, "subtest": "AR", "stem": "A blouse normally costs $18.50.\nHow much money is saved if the blouse is purchased at a 20% discount?", "options": {"A": "$1.85", "B": "$14.80", "C": "$4.50", "D": "$3.70"}, "answer": "D", "answer_raw": "D", "explanation": "Multiply the price of the blouse by the amount of the discount: $18.50 \u00d7 0.20 = $3.70.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 20, "excluded": false}, {"id": "AR-0049", "source_number": 49, "subtest": "AR", "stem": "A clerk's weekly salary of $320 is increased to $360.\nThe percent increase is __________.", "options": {"A": "101/2%", "B": "11%", "C": "121/2%", "D": "12%"}, "answer": "C", "answer_raw": "C", "explanation": "Subtract the original salary from the new salary to get the difference in salary: $360 - $320 =\n$40. Then divide the difference in salary ($40) by the original salary ($320) to determine the\npercent increase: 40 \u00f7 320 = 0.125 = 12.5%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 20, "excluded": false}, {"id": "AR-0050", "source_number": 50, "subtest": "AR", "stem": "Two go-carts are racing on a circular track with a perimeter of 360 feet. Camera One is following\nGo-Cart One, and Camera Two is following Go-Cart Two.\nIf the angle between the two cameras is 40 degrees, how far apart are the two go-carts?", "options": {"A": "30 feet", "B": "40 feet", "C": "300 feet", "D": "400 feet"}, "answer": "B", "answer_raw": "B", "explanation": "A circle is 360 degrees, so 40 degrees is 1/9 of a circle (360 \u00f7 40 = 9). To get the answer of 40\n\n\n\nfeet, multiply the perimeter of the track 1/9 (360 \u00d7 1/9 = 40).", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 4, "flags": [], "page": 20, "excluded": false}, {"id": "AR-0051", "source_number": 51, "subtest": "AR", "stem": "Dinner at a nice restaurant cost $35.98.\nIf Joan gave the cashier $40.00, how much change should she get back?", "options": {"A": "$5.02", "B": "$4.02", "C": "$3.92", "D": "$1.02"}, "answer": "B", "answer_raw": "B", "explanation": "Subtract $35.98 from $40.00 to get $4.02.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 21, "excluded": false}, {"id": "AR-0052", "source_number": 52, "subtest": "AR", "stem": "A balloonist circumnavigated the globe in 13 days, 12 hours, 16 minutes, and 13 seconds. A\nplane circumnavigates the globe in 4 days, 10 hours, 15 minutes, and 7 seconds.\nHow much longer did it take for the balloon to go around the world?", "options": {"A": "12 days, 7 hours, 11 minutes, and 35 seconds", "B": "9 days, 2 hours, 1 minute, and 6 seconds", "C": "8 days, 14 hours, 16 minutes, and 6 seconds", "D": "9 days, 7 hours, 3 minutes, and 20 seconds"}, "answer": "B", "answer_raw": "B", "explanation": "Subtract the speed of the plane from the speed of the balloon to determine how much longer it\ntook the balloonist:\n13 days 12 hours 16 minutes 13 seconds\n4 days 10 hours 15 minutes 7 seconds\n9 days 2 hours 1 minute 6 seconds", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 5, "flags": ["tag_fallback"], "page": 21, "excluded": false}, {"id": "AR-0053", "source_number": 53, "subtest": "AR", "stem": "Darlene bought 12 boxes of cookies for $48.00.\nWhat was the cost of each box of cookies?", "options": {"A": "$4.00", "B": "$0.48", "C": "$0.40", "D": "$4.80"}, "answer": "A", "answer_raw": "A", "explanation": "Divide the total cost by the number of boxes purchased to determine the cost per box: $48 \u00f7 12\n\n\n\n= $4.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 21, "excluded": false}, {"id": "AR-0054", "source_number": 54, "subtest": "AR", "stem": "A tune-up increases a car's fuel efficiency by 5%.\nIf a car averaged 20 miles per gallon before the tune-up, how many miles per gallon will it\naverage after the tune-up?", "options": {"A": "25", "B": "22", "C": "201/2", "D": "21"}, "answer": "D", "answer_raw": "D", "explanation": "Multiply 20 \u00d7 0.05 to determine how many more miles per gallon the car will get. The answer is\n1. Then add the number of additional miles per gallon the car will get to the original number of\nmiles per gallon the car gets to reach the new average: 1 + 20 = 21.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "rate_time_distance", "percentages_discount"], "difficulty": 4, "flags": [], "page": 22, "excluded": false}, {"id": "AR-0055", "source_number": 55, "subtest": "AR", "stem": "If you pay $22.90 for a DVD that includes a 7% sales tax, what is the price of the DVD before\nthe sales tax?", "options": {"A": "$21.40", "B": "$21.30", "C": "$21.50", "D": "$20.95"}, "answer": "A", "answer_raw": "A", "explanation": "If y represents the price of the DVD before the tax. Then price with tax would be y + 0.07y =\n$22.90. Therefore, 1.07y = 22.90, or y = 22.90/1.07 = $21.40. Be careful not to just take 7% of\n$22.90 and subtract. That is incorrect.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 22, "excluded": false}, {"id": "AR-0056", "source_number": 56, "subtest": "AR", "stem": "A bin of hard candy holds 101/2 pounds.\nHow many 3/4-pound boxes of candy can be filled from the bin?", "options": {"A": "30 boxes", "B": "151/4 boxes", "C": "77/8 boxes", "D": "14 boxes"}, "answer": "D", "answer_raw": "D", "explanation": "Divide 101/2 by 3/4. You can perform this operation by multiplying 101/2 by the inverse of 3/4:\n\n\n\n101/2 \u00d7 4/3 = 21/2 \u00d7 4/3 = 84/6. This fraction, reduced, becomes 14.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 22, "excluded": false}, {"id": "AR-0057", "source_number": 57, "subtest": "AR", "stem": "A patio measures 12 feet by 14 feet.\nHow many 8-inch-square paving stones are needed to pave the patio?", "options": {"A": "21", "B": "252", "C": "32", "D": "168"}, "answer": "B", "answer_raw": "B", "explanation": "First multiply length \u00d7 width to determine the area of the patio: 12 feet \u00d7 14 feet = 168 square\nfeet. Next determine the area in square inches that needs to be covered: 168 square feet \u00d7 12\ninches = 2,016 square inches. Finally, divide that answer by the size of the stones to determine\nthe number of stones needed: 2,016 \u00f7 8 = 252.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 23, "excluded": false}, {"id": "AR-0058", "source_number": 58, "subtest": "AR", "stem": "A computer programmer is making $25,000 per year. 28% of her salary is withheld for federal\nand state deductions.\nHow much is the computer programmer's net pay?", "options": {"A": "$20,000", "B": "$7,000", "C": "$18,750", "D": "$18,000"}, "answer": "D", "answer_raw": "D", "explanation": "Calculate the amount of the deduction by multiplying her salary by the percent deducted:\n$25,000 \u00d7 28% = $25,000 \u00d7 0.28 = $7,000. Subtract that product from the salary to determine\nthe net pay: $25,000 - $7,000 = $18,000.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 23, "excluded": false}, {"id": "AR-0059", "source_number": 59, "subtest": "AR", "stem": "Pam cuts a pie in half in a straight line. She then cuts a line from the center to the edge,\ncreating a 55-degree angle.\nWhat's the supplement of that angle?", "options": {"A": "55 degrees", "B": "125 degrees", "C": "70 degrees", "D": "130 degrees"}, "answer": "B", "answer_raw": "B", "explanation": "When the sum of two angles is 180 degrees, the angles are said to be supplemental to each\nother. To find the supplement, subtract 55 from 180 (180 - 55 = 125).", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 23, "excluded": false}, {"id": "AR-0060", "source_number": 60, "subtest": "AR", "stem": "A stack of lumber is 6-feet high.\nIf each piece of lumber is 4-inches thick, how many pieces of lumber are in the stack?", "options": {"A": "72", "B": "12", "C": "18", "D": "10"}, "answer": "C", "answer_raw": "C", "explanation": "Multiply the height of the stack in feet by 12 to determine the height of the stack in inches: 6 \u00d7\n12 = 72 inches.\nDivide that number by 4 inches, the thickness of each board to determine the number of pieces\nof lumber in the stack: 72 \u00f7 4 = 18.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 24, "excluded": false}, {"id": "AR-0061", "source_number": 61, "subtest": "AR", "stem": "A baker sells a dozen donuts for $3.99.\nThe cost to make three donuts is $0.45. How much is the total profit on 5-dozen donuts?", "options": {"A": "$17.70", "B": "$13.20", "C": "$2.19", "D": "$10.95"}, "answer": "D", "answer_raw": "D", "explanation": "Multiply $0.45 (the cost of making 3 donuts) by 4 to find the cost of making a dozen donuts:\n$0.45 \u00d7 4 = $1.80.\nThen multiply the cost of making a dozen donuts by 5 to determine the cost per 5 dozen: $1.80\n\u00d7 5 = $9.00.\nNext, multiply the selling price per dozen times 5, the number of dozens sold: $3.95 \u00d7 5 =\n$19.95. Finally subtract the cost of making 5-dozen donuts from the price the baker sells them\nfor to determine the profit:\n$19.95 - $9.00 = $10.95.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": [], "page": 24, "excluded": false}, {"id": "AR-0062", "source_number": 62, "subtest": "AR", "stem": "Your piggy bank contains $19.75 in dimes and quarters. There are 100 coins in all.\nHow many dimes are there?", "options": {"A": "25", "B": "30", "C": "35", "D": "40"}, "answer": "C", "answer_raw": "C", "explanation": "Let x equal the number of dimes. Then 100 - x represents the number of quarters.\nThere is $0.10x in dimes and $0.25(100 - x) in quarters.\n0.10x + 0.25(100 - x) = 19.75\n0.10x + 25 - 0.25x = 19.75\n-0.15x = -5.25\nx = -5.25/-0.15\nx = 35", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 24, "excluded": false}, {"id": "AR-0063", "source_number": 63, "subtest": "AR", "stem": "A bricklayer charges $8 per square foot to lay a patio.\nHow much would it cost for the bricklayer to lay a 12-foot \u00d7 16-foot patio?", "options": {"A": "$960", "B": "$192", "C": "$224", "D": "$1,536"}, "answer": "D", "answer_raw": "D", "explanation": "First determine the square footage of the patio: 12 feet \u00d7 16 feet = 192 square feet. Then\nmultiply this number by the cost per square foot to determine what the brick layer charges:\n192 \u00d7 $8 = $1,536.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 25, "excluded": false}, {"id": "AR-0064", "source_number": 64, "subtest": "AR", "stem": "Terry earns three times more per hour than Tim. Tim earns $2 more per hour than Angie. As a\ngroup they earn $43 per hour.\nWhat's Angie's hourly wage?", "options": {"A": "$7.00", "B": "$8.00", "C": "$9.00", "D": "$10.00"}, "answer": "A", "answer_raw": "A", "explanation": "Let x equal Angie's hourly wage. x + 2 would then represent Tim's hourly wage, and 3(x + 2)\nwould represent Terry's hourly wage.\nx + (x +2) + 3(x +2) = 43\nx + x + 2 + 3x + 6 = 43\n5x + 8 = 43\n5x = 35\n\n\n\nx = 35/5\nx = 7", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 3, "flags": [], "page": 25, "excluded": false}, {"id": "AR-0065", "source_number": 65, "subtest": "AR", "stem": "If 4 people can run 8 machines, how many machines can 2 people run?", "options": {"A": "2", "B": "4", "C": "1", "D": "3"}, "answer": "B", "answer_raw": "B", "explanation": "Two people is 1/2 as many as 4 people: 2 \u00f7 4 = 1/2. Multiply the number of machines 4 people\ncan run by 1/2 to determine how many machines 2 people can run: 8 \u00d7 1/2 = 4.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 26, "excluded": false}, {"id": "AR-0066", "source_number": 66, "subtest": "AR", "stem": "The price of daily admission at an amusement park is $36. The park sells an unlimited season\npass for $240.\nHow many trips would you need to make with the season ticket in order for it to cost less than\npaying the daily admission rate?", "options": {"A": "6", "B": "7", "C": "8", "D": "9"}, "answer": "B", "answer_raw": "B", "explanation": "Let x equal the number of daily tickets you would purchase. 36x = the daily ticket cost.\n240 < 36x\n240/36 < x\n62/3 < x\nYou would need to use the ticket more than 62/3 times (or 7 times) in order for it to be cheaper\nto use the season ticket.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 26, "excluded": false}, {"id": "AR-0067", "source_number": 67, "subtest": "AR", "stem": "A plumber needs four lengths of pipe, each 3-feet, 6-inches long. Pipes are sold by the foot.\nHow many feet does he need to buy?", "options": {"A": "15", "B": "16", "C": "14", "D": "12"}, "answer": "C", "answer_raw": "C", "explanation": "Convert the pipe length to inches: 3 feet, 6 inches = 42 inches. Multiply 42 inches by the\nnumber of pipes needed to find the number of inches of pipe needed: 42 \u00d7 4 = 168. Divide the\ntotal amount of pipe needed in inches by 12 to determine how many feet of pipes are needed:\n168 \u00f7 12 = 14.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 26, "excluded": false}, {"id": "AR-0068", "source_number": 68, "subtest": "AR", "stem": "The product of two consecutive odd numbers is 399.\nWhat are the numbers?", "options": {"A": "17 and 19", "B": "19 and 21", "C": "21 and 23", "D": "25 and 27"}, "answer": "B", "answer_raw": "B", "explanation": "The fastest way to solve this would be to simply multiply the possible choices together (19 \u00d7 21\n= 399). You can also solve this with algebra.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 27, "excluded": false}, {"id": "AR-0069", "source_number": 69, "subtest": "AR", "stem": "A personal trainer earns a 65% commission on her training sales.\nIf she sells $530.00 worth of training, how much commission does she make?", "options": {"A": "$874.50", "B": "$34.45", "C": "$344.50", "D": "$185.50"}, "answer": "C", "answer_raw": "C", "explanation": "Multiply her total sales by her percent commission to find her commission: $530.00 \u00d7 0.65 =\n$344.50.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 27, "excluded": false}, {"id": "AR-0070", "source_number": 70, "subtest": "AR", "stem": "A rectangle is one inch longer than it is wide. Its diameter is five inches.\nWhat's the width of the rectangle?", "options": {"A": "2 inches", "B": "3 inches", "C": "4 inches", "D": "5 inches"}, "answer": "B", "answer_raw": "B", "explanation": "The diagonal formula for a rectangle is D2 = L2 + W2. In this case, D = 5, and L = W + 1.\nSubstituting the known values into the formula results in 52 = (W + 1)2 + W2.\n25 = (W + 1)(W + 1) + W2\n25 = W2 + 2W + 1 + W2\n25 = 2W2 + 2W + 1\n(Note: This equation is a quadratic equation and can be solved by setting it equal to zero and\nfactoring.) 0 = 2W2 + 2W - 24\n1/2(0) = 1/2(2 W2 + 2W - 24)\n0 = W2 + W - 12\n0 = (W - 3)(W + 4)\nW - 3 = 0W + 4 = 0\nW = 3\nW = -4 (not a possible solution)", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 27, "excluded": false}, {"id": "AR-0071", "source_number": 71, "subtest": "AR", "stem": "A treasure map is drawn to a scale of 2 inches = 3 miles. On the map, the distance between\nPoint A and X- marks-the-spot is 91/2 inches.\nHow many actual miles does this represent?", "options": {"A": "281/2 miles", "B": "141/4 miles", "C": "61/3 miles", "D": "19 miles"}, "answer": "B", "answer_raw": "B", "explanation": "If 2 inches = 3 miles, then 1 inch equals 11/2 miles: 3 \u00f7 2 = 1.5. Multiply 11/2 miles \u00d7 91/2\ninches to determine the actual distance: 1.5 \u00d7 9.5 = 14.25 or 141/4 miles.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 5, "flags": [], "page": 28, "excluded": false}, {"id": "AR-0072", "source_number": 72, "subtest": "AR", "stem": "A painter has painted a picture on a piece of canvas that measures 10 \u00d7 14 inches. In order to\naccommodate a frame, he has left an unpainted margin of 1 inch all the way around.\nWhat part of the canvas has been painted?", "options": {"A": "80%", "B": "75%", "C": "25%", "D": "66%"}, "answer": "A", "answer_raw": "A", "explanation": "The area of the entire piece of canvas = 10 inches \u00d7 14 inches = 140 square inches. The\nportion painted on equals 8 inches \u00d7 12 inches = 112 square inches. (This is determined by\nsubtracting 1 inch from the length of each side to account for the margin.) The portion used for\npainting can be expressed as a fraction: 112/140.\nReduce this fraction (divide 112 by 140) to determine that 80% of the canvas is covered with\n\n\n\npaint.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 28, "excluded": false}, {"id": "AR-0073", "source_number": 73, "subtest": "AR", "stem": "A dog trainer is building a dog run that measures 9 \u00d7 16 feet.\nIf she wants to fence the perimeter of the run, how many feet of chain link fence will she need?", "options": {"A": "144 feet", "B": "25 feet", "C": "32 feet", "D": "50 feet"}, "answer": "D", "answer_raw": "D", "explanation": "Calculate perimeter by adding the lengths of all four sides of a quadrilateral: 9 + 9 + 16 + 16 =\n50 feet.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 2, "flags": [], "page": 29, "excluded": false}, {"id": "AR-0074", "source_number": 74, "subtest": "AR", "stem": "A rectangle is 11/2 times as long as it is wide. The perimeter of the rectangle is 100 inches.\nWhat's the length of the rectangle?", "options": {"A": "20 inches", "B": "30 inches", "C": "40 inches", "D": "45 inches"}, "answer": "B", "answer_raw": "B", "explanation": "The formula for the perimeter of a rectangle is P = 2L + 2W. In this case, P = 100 and L = 1.5W.\n100 = 2(1.5W) + 2W\n100 = 3W + 2W\n100 = 5W\nW = 100/5\nW = 20.\nThe width of the rectangle is 20 inches. Because the length is 11/2 the width, 1.5 \u00d7 20 = 30.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 29, "excluded": false}, {"id": "AR-0075", "source_number": 75, "subtest": "AR", "stem": "Miguel passed seven of his history class quizzes and failed three.\nThe fraction of quizzes he passed is correctly expressed as __________.", "options": {"A": "7/3", "B": "3/7", "C": "7/10", "D": "3/5"}, "answer": "C", "answer_raw": "C", "explanation": "The total number of quizzes is 10. If he passed seven of them, the fraction would be expressed\nas 7/10.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 1, "flags": [], "page": 29, "excluded": false}, {"id": "AR-0076", "source_number": 76, "subtest": "AR", "stem": "A 3-yard-long ribbon was used to trim four dresses. Each dress used the same amount of\nribbon.\nHow much ribbon was used for each dress?", "options": {"A": "1 yard", "B": "2/3 yard", "C": "1/2 yard", "D": "3/4 yard"}, "answer": "D", "answer_raw": "D", "explanation": "Convert the measurement to inches: 1 yard = 36 inches; 36 inches \u00d7 3 = 108 inches.\nDivide the total number of inches by the number of dresses being trimmed to determine the\nlength of each piece of ribbon: 108 inches \u00f7 4 = 27 inches. Convert the quotient (27 inches) to a\nfraction of a yard: 27/36 = 27 \u00f7 36 = 75% = 3/4 of a yard.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 30, "excluded": false}, {"id": "AR-0077", "source_number": 77, "subtest": "AR", "stem": "Sarah found a wallet containing $500 in the street. She returned the wallet to its owner, who\ngave her a $30 reward.\nWhat percentage of the $500 was the reward?", "options": {"A": "5%", "B": "6%", "C": "7%", "D": "4%"}, "answer": "B", "answer_raw": "B", "explanation": "Divide $30 by $500 to determine the percentage of $500 that the reward comprised.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 30, "excluded": false}, {"id": "AR-0078", "source_number": 78, "subtest": "AR", "stem": "A bin of bolts at the hardware store contains 7-dozen bolts when full. The stock clerk is\nsupposed to reorder bolts when the bin is 1/6 full.\nHow many bolts are in the bin when it's time to reorder?", "options": {"A": "14 bolts", "B": "1 bolt", "C": "84 bolts", "D": "12 bolts"}, "answer": "A", "answer_raw": "A", "explanation": "First find how many bolts a full bin contains: 7 \u00d7 12 = 84 bolts. Then multiply the total number of\nbolts in a full bin by 1/6 to find how many bolts are in the bin when it's 1/6 full:\n84/1 \u00d7 1/6 = 84/6 = 14 bolts.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 30, "excluded": false}, {"id": "AR-0079", "source_number": 79, "subtest": "AR", "stem": "Two bicyclists head toward each other from the opposite ends of Main Street, which is six miles\nlong. The first biker started at 2:05 going 12 mph. The second biker began peddling 4 minutes\nlater at a rate of 14 mph.\nWhat time will they meet?", "options": {"A": "2:13", "B": "2:24", "C": "2:29", "D": "2:34"}, "answer": "C", "answer_raw": "C", "explanation": "The first bike got a 4/5 mile head start (12 \u00d7 4/60). Therefore, by the time the second bike\nleaves, there are 51/5 miles between them (6 - 4/5). Their combined rate of travel is 12 + 14 =\n26 mph. Let t = the number of hours the second bike travels.\n26t = 51/5\n26t = 26/5\nt = 26/5 \u00f7 26/1\nt = 26/5 \u00d7 1/26\nt = 1/5\n1/5 of an hour = 20 minutes. The second bike left at 2:09, so both bikes will meet at 2:29.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 4, "flags": [], "page": 31, "excluded": false}, {"id": "AR-0080", "source_number": 80, "subtest": "AR", "stem": "A recipe calls for 8 ounces of black beans or red beans.\nThe cheapest option to buy and use would be __________.", "options": {"A": "two 4-ounce cans of black beans at $0.79 each", "B": "one 8-ounce can of red beans at $1.49", "C": "two 3-ounce cans of black beans at $0.59 each", "D": "three 3-ounce cans of red beans at $0.65 each"}, "answer": "B", "answer_raw": "B", "explanation": "Choice (one 8-ounce can of red beans at $1.49) is the cheapest option. Calculate each answer\noption and compare:\nChoice (two 4-ounce cans of black beans at $0.79 each): 2 \u00d7 $0.79 = $1.58.\nChoice (one 8-ounce can of red beans at $1.49): $1.49.\nChoice (two 3-ounce cans of black beans at $0.59 each): Two 3-ounce cans don't equal 8\nounces, so this answer can't be correct.\nChoice (three 3-ounce cans of red beans at $0.65 each): 3 \u00d7 $0.65 = $1.95.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 31, "excluded": false}, {"id": "AR-0081", "source_number": 81, "subtest": "AR", "stem": "A street vendor sells $25.70 worth of pretzels on Friday, $32.30 on Saturday, and $31.80 on\nSunday. He spends a fourth of the money over the weekend.\nHow much money does he have left?", "options": {"A": "$89.80", "B": "$22.45", "C": "$44.90", "D": "$67.35"}, "answer": "D", "answer_raw": "D", "explanation": "Add the sales amounts together: $25.70 + $32.30 + $31.80 = $89.80. Then multiply the total\nsales by 3/4 to determine how much money he has left: $89.80 \u00d7 0.75 = $67.35.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 32, "excluded": false}, {"id": "AR-0082", "source_number": 82, "subtest": "AR", "stem": "A recruit has $30.00. He saw some camouflage socks for $3.95 a pair.\nHow many pairs of socks can he buy?", "options": {"A": "9", "B": "7", "C": "6", "D": "4"}, "answer": "B", "answer_raw": "B", "explanation": "Divide $30.00 by $3.95. The whole number is the number of pairs of socks he could buy: $30.00\n\u00f7 $3.95 = 7.59 or 7 pairs of socks.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 32, "excluded": false}, {"id": "AR-0083", "source_number": 83, "subtest": "AR", "stem": "A crate containing a puppy weighs 60 pounds, 5 ounces. The puppy weighs 43 pounds, 7\nounces.\nHow much does the crate alone weigh?", "options": {"A": "16 pounds, 8 ounces", "B": "16 pounds, 2 ounces", "C": "17 pounds", "D": "16 pounds, 14 ounces"}, "answer": "D", "answer_raw": "D", "explanation": "16 ounces make a pound. Subtract 43 pounds, 7 ounces (the weight of the puppy) from 59\npounds, 21 ounces (the weight of the crate). 59 pounds, 21 ounces is the same as 60 pounds, 5\nounces, but converting an additional pound to ounces makes the subtraction possible.\n\n\n\n59 pounds, 21 ounces - 43 pounds, 7 ounces =16 pounds, 14 ounces", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 32, "excluded": false}, {"id": "AR-0084", "source_number": 84, "subtest": "AR", "stem": "In a manufacturing plant that produces new computers, a 0.15 probability exists that a computer\nwill be defective.\nIf five computers are manufactured, what's the probability that all of them will be defective?", "options": {"A": "7.6", "B": "0.60", "C": "0.00042", "D": "0.000076"}, "answer": "D", "answer_raw": "D", "explanation": "The probability that all five computers will be defective is 0.15 \u00d7 0.15 \u00d7 0.15 \u00d7 0.15 \u00d7 0.15 =\n0.0000759 (round up to 0.000076)", "figure": null, "passage_id": null, "topics": ["basic_probability"], "difficulty": 2, "flags": [], "page": 33, "excluded": false}, {"id": "AR-0085", "source_number": 85, "subtest": "AR", "stem": "A house contains one 12-foot \u00d7 14-foot bedroom, one 12-foot \u00d7 10-foot bedroom, and one 8-\nfoot \u00d7 12-foot bedroom.\nWhat's the total amount of carpeting needed to carpet all three bedrooms?", "options": {"A": "384 square yards", "B": "128 square yards", "C": "216 square yards", "D": "88 square yards"}, "answer": "B", "answer_raw": "B", "explanation": "Find the area of each bedroom and add them together: 12 \u00d7 14 = 168; 12 \u00d7 10 = 120; 8 \u00d7 12 =\n96. 168 + 120 + 96 = 384 square feet. Then, because 3 feet make up a yard, divide the total\narea in square feet by 3 to determine the number of square yards needed: 384 \u00f7 3 = 128 square\nyards.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 5, "flags": [], "page": 33, "excluded": false}, {"id": "AR-0086", "source_number": 86, "subtest": "AR", "stem": "Rafael can type 9 pages an hour.\nHow long will it take him to type 126 pages?", "options": {"A": "14 hours", "B": "9 hours", "C": "7 hours", "D": "16 hours"}, "answer": "A", "answer_raw": "A", "explanation": "Divide the total number of pages to be typed by the number of pages Rafael can type per hour\nto find the number of hours it will take him to type the pages: 126 pages \u00f7 9 pages per hour =\n14 hours.", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 1, "flags": [], "page": 33, "excluded": false}, {"id": "AR-0087", "source_number": 87, "subtest": "AR", "stem": "In a 60-minute gym class, 40 girls want to play volleyball, but only 10 can play at a time.\nFor each player to get the same amount of playing time, how many minutes should each person\nplay?", "options": {"A": "11/2 minutes", "B": "6 minutes", "C": "30 minutes", "D": "15 minutes"}, "answer": "D", "answer_raw": "D", "explanation": "Divide the group of 40 girls by the number of girls who can play at the same time: 40 \u00f7 10 = 4.\nThis means 4 groups of girls have to share the 60 minutes or 60 minutes \u00f7 4 = 15 minutes.\nThus, each girl plays for 15 minutes.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 34, "excluded": false}, {"id": "AR-0088", "source_number": 88, "subtest": "AR", "stem": "The video-rental store charges $2.00 for the first day a rented video is overdue and $1.25 for\neach day after that.\nIf a person paid $8.25 in late fees, how many days was the video overdue?", "options": {"A": "7 days", "B": "6 days", "C": "4 days", "D": "5 days"}, "answer": "B", "answer_raw": "B", "explanation": "Subtract the first day's late charge from the total: $8.25 - $2.00 = $6.25.\nThen divide the remainder by $1.25 to determine the number of additional days the video was\noverdue: $6.25 \u00f7 $1.25 = 5.\nAdd those 5 days to the first day the video was late, to find that the video was 6 days overdue.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 34, "excluded": false}, {"id": "AR-0089", "source_number": 89, "subtest": "AR", "stem": "Janet is trying to watch her weight. A 1/2 cup of pudding has 150 calories. The same amount of\nbroccoli has 60 calories.\nHow much broccoli can Janet eat to equal the same number of calories in the 1/2 cup of\npudding?", "options": {"A": "2 cups", "B": "21/2 cups", "C": "11/2 cups", "D": "11/4 cups"}, "answer": "D", "answer_raw": "D", "explanation": "Divide the number of calories in the pudding by the number of calories in the broccoli: 150 \u00f7 60\n= 21/2. Janet can eat 21/2 times the amount of broccoli as she can eat pudding for the same\nnumber of calories. Multiply 21/2 by 1/ 2 cup (the amount of pudding that contains 150 calories)\nto find how many cups of broccoli she can eat for 150 calories: 2.5 \u00d7 0.5 = 1.25 or 11/4 cups.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 5, "flags": ["tag_fallback"], "page": 34, "excluded": false}, {"id": "AR-0090", "source_number": 90, "subtest": "AR", "stem": "The neighbor's dog barks at a squirrel every 15 minutes at night.\nIf he first barks at 10 p.m., when you're trying to fall asleep, how many times will he bark by 2\na.m., when you give up trying to sleep and decide to read a book instead?", "options": {"A": "16 times", "B": "132 times", "C": "17 times", "D": "15 times"}, "answer": "C", "answer_raw": "C", "explanation": "The time between 10 p.m. and 2 a.m. is 4 hours or 240 minutes. Divide the total number of\nminutes in the time period by 15 minutes - the interval that the dog barks. Then add 1 because\nthe dog started barking at the beginning of the period: (240 \u00f7 15) + 1 = 17.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 35, "excluded": false}, {"id": "AR-0091", "source_number": 91, "subtest": "AR", "stem": "If a barber is capable of cutting the hair of 35 people per day, and he works 7 days per week,\nhow many haircuts could he give during the months of April, May, and June?", "options": {"A": "3185", "B": "3150", "C": "2545", "D": "2555"}, "answer": "A", "answer_raw": "A", "explanation": "There are 30 days in April, 31 days in May, and 30 days in June for a total of 91 days.\n91 \u00d7 35 = 3185.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 35, "excluded": false}, {"id": "AR-0092", "source_number": 92, "subtest": "AR", "stem": "If you typed 45 words per minute, how many words would you be able to type in 12 minutes?", "options": {"A": "490", "B": "540", "C": "605", "D": "615"}, "answer": "B", "answer_raw": "B", "explanation": "Multiply the number of words you can type per minute (45) by the number of minutes you will be\ntyping (12). 45 \u00d7 12 = 540.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 1, "flags": [], "page": 35, "excluded": false}, {"id": "AR-0093", "source_number": 93, "subtest": "AR", "stem": "Tom is flying a kite at the end of a 500-foot string. His friend Kathy is standing directly under the\nkite 300 feet away from Tom.\nHow high is the kite flying?", "options": {"A": "300 feet", "B": "350 feet", "C": "400 feet", "D": "450 feet"}, "answer": "C", "answer_raw": "C", "explanation": "Visualize a triangle, where the string represents the hypotenuse and the line between Tom and\nKathy represents one of the legs. The Pythagorean theorem states that if one knows the length\nof two sides of a triangle, the length of the third side can be determined, using the formula a2 +\nb2 = c2. In this case, 3002 + b2 = 5002.\n90,000 + b2 = 250,000\nb2 = 250,000 - 90,000\nb2 = 160,000\nb = 160,000\nb = 400", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 36, "excluded": false}, {"id": "AR-0094", "source_number": 94, "subtest": "AR", "stem": "Amy wants to fence in a yard using 400 feet of fencing.\nIf she wants the yard to be 30-feet wide, how long will it be?", "options": {"A": "170 feet", "B": "175 feet", "C": "180 feet", "D": "185 feet"}, "answer": "A", "answer_raw": "A", "explanation": "The formula used to determine the perimeter of a rectangle is P = 2(L + W). The width is 30,\nand the parameter is 400.\n400 = 2(L + 30)\n400 = 2L + 60\n340 = 2L\nL = 170", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 2, "flags": [], "page": 36, "excluded": false}, {"id": "AR-0095", "source_number": 95, "subtest": "AR", "stem": "A three-digit code must be used to access a computer file. The first digit must be an A or a B.\nThe second digit must be a number between 0 and 9. The final digit is a single letter from the\nalphabet from A to Z.\nHow many possible access codes can there be?", "options": {"A": "38", "B": "468", "C": "520", "D": "640"}, "answer": "C", "answer_raw": "C", "explanation": "There are 2 possibilities for the first digit (A or B), 10 possibilities for the second digit (0 to 9)\nand 26 possibilities for the third digit. Using the multiplication principle, 2 \u00d7 10 \u00d7 26 = 520", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 37, "excluded": false}, {"id": "AR-0096", "source_number": 96, "subtest": "AR", "stem": "The sun is 93 million miles from Earth and light travels at a rate of 186,000 miles per second.\nHow long does it take for light from the sun to reach the Earth?", "options": {"A": "5 minutes", "B": "61/2 minutes", "C": "7 minutes", "D": "81/2 minutes"}, "answer": "D", "answer_raw": "D", "explanation": "Use the time formula T = S \u00f7 V, where T = time, S = displacement, V = velocity. Time (T) = 93\nmillion miles (S) \u00f7 186,000 miles per second (V) = 500 second. 500 second = 81/2 minutes.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 2, "flags": [], "page": 37, "excluded": false}, {"id": "AR-0097", "source_number": 97, "subtest": "AR", "stem": "A tanning-bed pass for unlimited tanning costs $53 per month this year, but it was only $50 per\nmonth last year.\nWhat was the percentage of increase?", "options": {"A": "5%", "B": "5.5%", "C": "6%", "D": "6.5%"}, "answer": "C", "answer_raw": "C", "explanation": "The difference in the price is $3. $3 \u00f7 $50 = 0.06 or 6%", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 37, "excluded": false}, {"id": "AR-0098", "source_number": 98, "subtest": "AR", "stem": "Eleven plus forty-one is divided by a number.\nIf the result is 13, what's the number?", "options": {"A": "2", "B": "4", "C": "6", "D": "8"}, "answer": "B", "answer_raw": "B", "explanation": "11 + 41 =52\nCalculate each answer option to figure out the correct answer:\n52 \u00f7 2 = 26\n52 \u00f7 4 = 13\n52 \u00f7 6 = 8,67\n52 \u00f7 8 = 6,5", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 38, "excluded": false}, {"id": "AR-0099", "source_number": 99, "subtest": "AR", "stem": "Mark received an hourly wage of $9.25. His boss gave him a 4% raise.\nHow much does Mark make per hour now?", "options": {"A": "$9.29", "B": "$9.62", "C": "$9.89", "D": "$9.99"}, "answer": "B", "answer_raw": "B", "explanation": "To calculate the new wage, start off by taking $9.25 \u00d7 0.04 = $0.37. Then add that number (the\namount of Mark's raise) to his original hourly wage. Mark's new hourly wage is $9.25 + $0.37 =\n$9.62.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "work_rate", "rate_time_distance"], "difficulty": 3, "flags": [], "page": 38, "excluded": false}, {"id": "AR-0100", "source_number": 100, "subtest": "AR", "stem": "How many pounds of nails costing $7 per pound must be mixed with 6 pounds of nails costing\n$3 per pound to yield a mixture costing $4 per pound?", "options": {"A": "2 pounds", "B": "2.5 pounds", "C": "3 pounds", "D": "3.5 pounds"}, "answer": "A", "answer_raw": "A", "explanation": "Let x = number of nails costing $7 per pound. The total cost of the mixture equals the sum of the\n\n\n\ncost for each type of nail or M = A + B, where A = 7x, B = 3(6), and M = 4(6 + x). Substitute the\nknown values into the equation. 4(6 + x) = 7x + 18.\n24 + 4x = 7x + 18\n24 - 18 = 7x - 4x\n3x = 6\nx = 2", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 38, "excluded": false}, {"id": "AR-0101", "source_number": 101, "subtest": "AR", "stem": "A product originally costs $125.\nIf the product goes on sale for 20% off, and then goes on sale for an additional 30% off, what is\nthe price of the product?", "options": {"A": "$62.50", "B": "$70", "C": "$65", "D": "$90"}, "answer": "B", "answer_raw": "B", "explanation": "You need to apply the discounts successively not just add the discounts. So $125 \u00d7 80% = $100\n(price after original 20% discount). $100 \u00d7 70% = $70 the price after the 2nd 30% discount.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 39, "excluded": false}, {"id": "AR-0102", "source_number": 102, "subtest": "AR", "stem": "A digital video recorder is programmed to record a TV show that lasts for a half hour.\nIf the digital video recorder has enough memory left to hold 180 minutes of recording, what\npercentage of the remaining capacity is used for this recording?", "options": {"A": "162/3%", "B": "30%", "C": "60%", "D": "331/3%"}, "answer": "A", "answer_raw": "A", "explanation": "A half-hour is 30 minutes.\nThe portion of 180 minutes represented by 30 minutes is 30/180 or 1/6. As a percentage, 1/6 is\n162/3%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 39, "excluded": false}, {"id": "AR-0103", "source_number": 103, "subtest": "AR", "stem": "On a trip to the beach you travel 200 miles in 300 minutes.\nHow fast did you travel?", "options": {"A": "30 mph", "B": "40 mph", "C": "50 mph", "D": "60 mph"}, "answer": "B", "answer_raw": "B", "explanation": "First convert the 300 minutes to hours by dividing by 60 (300 \u00f7 60 = 5 hours). Use the distance\nformula (d = rt) and substitute the known values. 300 = 5r. r = 40.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 1, "flags": [], "page": 39, "excluded": false}, {"id": "AR-0104", "source_number": 104, "subtest": "AR", "stem": "21 students, or 60% of the class, passed the final exam.\nHow many students are in the class?", "options": {"A": "45", "B": "40", "C": "35", "D": "30"}, "answer": "C", "answer_raw": "C", "explanation": "Let x = the number of people in the class.\n60% of x = 21, so 0.60x = 21.\nx = 35.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 40, "excluded": false}, {"id": "AR-0105", "source_number": 105, "subtest": "AR", "stem": "Joan invests $4,000 in an account that earns 3% simple interest.\nHow much will Joan have in the account in 10 years?", "options": {"A": "$4,500", "B": "$4,800", "C": "$5,200", "D": "$5,400"}, "answer": "C", "answer_raw": "C", "explanation": "Use the interest formula (I = Prt) to determine the amount of interest earned, where the principle\n(P) is 4,000, the rate (r) is 0.03 (3%) and the time (t) is 10. I = 4,000(0.03)(10), or I = $1,200.\nAdd the interest earned to the original amount invested. $4,000 + $1,200 = $5,200.", "figure": null, "passage_id": null, "topics": ["simple_interest", "percentages_discount"], "difficulty": 2, "flags": [], "page": 40, "excluded": false}, {"id": "AR-0106", "source_number": 106, "subtest": "AR", "stem": "A rectangle has a perimeter of 36 inches. Its length is 3 inches greater than twice the width.\nWhat's the rectangle's length?", "options": {"A": "5 inches", "B": "13 inches", "C": "18 inches", "D": "20 inches"}, "answer": "B", "answer_raw": "B", "explanation": "A rectangle's perimeter is determined by the formula P = 2(l + w). The length of this rectangle is\n3 + 2w.\nSubstituting the known values into the formula results in 36 = 2(w + 3 + 2w).\n36 = 2(3w + 3)\n18 = 3w + 3\n15 = 3w\nw = 5\nAs the length is 3 + 2w, then l = 3 + 2(5), or l = 13.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 40, "excluded": false}, {"id": "AR-0107", "source_number": 107, "subtest": "AR", "stem": "A back yard is 50 feet by 100 feet.\nWhat's its area?", "options": {"A": "150 square feet", "B": "500 square feet", "C": "2,500 square feet", "D": "5,000 square feet"}, "answer": "D", "answer_raw": "D", "explanation": "The area of a rectangle is the length \u00d7 the width of the rectangle. 50 \u00d7 100 = 5,000.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 41, "excluded": false}, {"id": "AR-0108", "source_number": 108, "subtest": "AR", "stem": "Eric is driving a car in which the speedometer is calibrated in kilometers per hour (kph). He\nnotes that his car is traveling at a rate of 75 kph, when he passes a speed limit sign stating the\nlimit is 40 miles per hour (mph). He knows that a kilometer is about 5/8 of a mile.\nIf a police officer stops him at this point, how many mph over the limit will the ticket read?", "options": {"A": "5", "B": "7", "C": "9", "D": "11"}, "answer": "B", "answer_raw": "B", "explanation": "A kilometer is 5/8 of a mile, so multiply 75 \u00d7 5/8, or 75/1 \u00d7 5/8 = 375/8. Divide 8 into 375 to\nreduce the fraction and determine that Eric was traveling at 47 miles per hour, 7 mph over the\n40 mph posted limit.", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 5, "flags": [], "page": 41, "excluded": false}, {"id": "AR-0109", "source_number": 109, "subtest": "AR", "stem": "Three apples and twice as many pears add up to one-half the number of grapes in a fruit\nbasket.\nHow many grapes are in the basket?", "options": {"A": "8", "B": "18", "C": "28", "D": "38"}, "answer": "B", "answer_raw": "B", "explanation": "Let x = the number of grapes. 3 apples and 6 pears equals 1/2 of x or 1/2(x) = 9. x = 2(9) or x =\n18.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 1, "flags": ["explanation_may_belong_to_next"], "page": 41, "excluded": false}, {"id": "AR-0110", "source_number": 110, "subtest": "AR", "stem": "Apples are on sale for \"Buy 2 get 1 free.\"\nHow many pounds must Janet purchase to get 2 pounds free?", "options": {"A": "2 pounds", "B": "4 pounds", "C": "6 apples", "D": "3 pounds"}, "answer": "B", "answer_raw": "B", "explanation": "If Janet must purchase 2 pounds of apples to get 1 free pound, to get 2 free pounds, she would\nneed to purchase twice as many apples or 4 pounds of apples.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "percentages_discount"], "difficulty": 1, "flags": [], "page": 42, "excluded": false}, {"id": "AR-0111", "source_number": 111, "subtest": "AR", "stem": "If 4 pipes of equal length measure 44 feet when they're connected together, how long is each\npipe?", "options": {"A": "11 feet", "B": "4 feet", "C": "22 feet", "D": "9 feet"}, "answer": "A", "answer_raw": "A", "explanation": "Divide the total length, 44 feet, by the total number of pipes, 4, because all the pipes are equal\nin length. The quotient, 11, is the length of each individual pipe. You can check this answer by\nmultiplying: 4 \u00d7 11 = 44.", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 1, "flags": [], "page": 42, "excluded": false}, {"id": "AR-0112", "source_number": 112, "subtest": "AR", "stem": "A German shepherd and an Alaskan Malamute are both headed toward the same fire hydrant.\nThe German Shepherd is 120 feet away from the hydrant and the Alaskan Malamute is 75 feet\naway from the hydrant.\nHow much closer to the hydrant is the Alaskan Malamute?", "options": {"A": "45 feet", "B": "25 feet", "C": "75 feet", "D": "195 feet"}, "answer": "A", "answer_raw": "A", "explanation": "Subtract the Malamute's distance from the German Shepherd's distance (120 - 75) to determine\nhow much closer the Malamute is to the hydrant.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 42, "excluded": false}, {"id": "AR-0113", "source_number": 113, "subtest": "AR", "stem": "A recruit reporting to boot camp took a bus from her home to the military processing center in\nanother city. The trip took 14 hours.\nIf she left at 6 a.m., what time did she arrive at the processing center?", "options": {"A": "7 p.m.", "B": "12 a.m.", "C": "8 p.m.", "D": "9 p.m."}, "answer": "C", "answer_raw": "C", "explanation": "Simply add 14 hours to 6 a.m. to reach 8 p.m.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 43, "excluded": false}, {"id": "AR-0114", "source_number": 114, "subtest": "AR", "stem": "A farmer sold 3 pints of strawberries for $1.98 each, 5 pints of raspberries for $2.49 each, and a\nbushel of peaches for $5.50 at his roadside stand.\nHow much money did the farmer make?", "options": {"A": "$9.97", "B": "$23.89", "C": "$18.39", "D": "$18.91"}, "answer": "B", "answer_raw": "B", "explanation": "Multiply three pints of strawberries at $1.98 (3 \u00d7 $1.98 = $5.94); 5 pints of raspberries at $2.49\n(5 \u00d7 $2.49 = $12.45) and 1 bushel of peaches at $5.50 (1 \u00d7 $5.50 = $5.50). Add the products\ntogether to determine the amount of cash the farmer earned: $5.94 + $12.45 + $5.50 = $23.89.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 4, "flags": [], "page": 43, "excluded": false}, {"id": "AR-0115", "source_number": 115, "subtest": "AR", "stem": "A librarian wants to shelve 532 books.\nIf 4 books fit on a 1-foot length of shelving, how many feet of shelving does she need to shelve\nall the books?", "options": {"A": "13", "B": "45", "C": "33", "D": "133"}, "answer": "D", "answer_raw": "D", "explanation": "Divide 532 by 4 to determine how many feet of shelving will be needed.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 2, "flags": [], "page": 43, "excluded": false}, {"id": "AR-0116", "source_number": 116, "subtest": "AR", "stem": "A student buys a science textbook for $18.00, a math textbook for $14.50, and a dictionary for\n$9.95.\nWhat's the total cost of the books?", "options": {"A": "$27.95", "B": "$42.45", "C": "$41.95", "D": "$38.50"}, "answer": "B", "answer_raw": "B", "explanation": "Simply add the cost of all the books: $18.00 + $14.50 + $9.95 = $42.45.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": [], "page": 44, "excluded": false}, {"id": "AR-0117", "source_number": 117, "subtest": "AR", "stem": "Debra works an 8-hour shift on Friday.\nHow many minutes does she work on Friday?", "options": {"A": "480 minutes", "B": "800 minutes", "C": "240 minutes", "D": "400 minutes"}, "answer": "A", "answer_raw": "A", "explanation": "8 hours \u00d7 60 minutes per hour = 480 minutes.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 44, "excluded": false}, {"id": "AR-0118", "source_number": 118, "subtest": "AR", "stem": "Six people can run 3 machines in the factory.\nHow many machines can 18 people run?", "options": {"A": "7", "B": "9", "C": "6", "D": "8"}, "answer": "B", "answer_raw": "B", "explanation": "If 6 people can run 3 machines, then 18 people can run 3 times the number of machines 6\npeople can run because 18 = 3 \u00d7 6 (divide 18 by 6). 3 \u00d7 3 machines = 9 machines. 18 people\ncan run 9 machines.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 44, "excluded": false}, {"id": "AR-0119", "source_number": 119, "subtest": "AR", "stem": "On a map drawn to scale, 1/2 inch equals 1 mile.\nWhat length on the map equals 5 miles?", "options": {"A": "2.5 inches", "B": "5.0 inches", "C": "10.0 inches", "D": "1.5 inches"}, "answer": "A", "answer_raw": "A", "explanation": "Multiply the scale measurement for 1 mile (1/2 inch per mile) by 5 miles: 1/2 \u00d7 5 or 1/2 \u00d7 5/1 =\n5/2. Reduce this fraction, and you get 2.5 inches.", "figure": null, "passage_id": null, "topics": ["ratio_proportion", "rate_time_distance"], "difficulty": 2, "flags": [], "page": 45, "excluded": false}, {"id": "AR-0120", "source_number": 120, "subtest": "AR", "stem": "A man bought a pair of jeans for $23.00, a shirt for $14.95, and two ties for $7.98 each.\nWhat was the total cost of his clothing?", "options": {"A": "$53.91", "B": "$45.93", "C": "$51.99", "D": "$54.50"}, "answer": "A", "answer_raw": "A", "explanation": "Simply add the cost of all the items: $23.00 + $14.95 + $7.98 + $7.98 = $53.91.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": [], "page": 45, "excluded": false}, {"id": "AR-0121", "source_number": 121, "subtest": "AR", "stem": "A rectangular block of brown metal folding chairs is set up on the floor of Reed Arena for the\nannual freshman convocation. The block of seats has x rows, withy folding chairs in each row.\nHow many folding chairs are there on the floor of the arena?", "options": {"A": "x + y", "B": "x - y", "C": "xy", "D": "y - x"}, "answer": "C", "answer_raw": "C", "explanation": "To calculate the number of total chairs on the floor of the arena, multiply the number of rows (x)\nby the number of chairs in each row (y). This equation is written as xy.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 45, "excluded": false}, {"id": "AR-0122", "source_number": 122, "subtest": "AR", "stem": "Jolie wants to get a new car before her second year of college. The sticker price of the kind of\ncar she wants went up from $22,399 last year to $23,999 for this year's model.\nWhat percentage did the price increase?", "options": {"A": "1.071%", "B": "7.1%", "C": "9.3%", "D": "71.4%"}, "answer": "B", "answer_raw": "B", "explanation": "First, calculate the amount of the price increase.\n$23,999 - $22,399=$1,600\nThen, calculate it as a percentage of the original price by multiplying it by 100 and then dividing\nby the original price:\n($1,600 \u00d7 100) / $22,399 = 7.1% increase", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 46, "excluded": false}, {"id": "AR-0123", "source_number": 123, "subtest": "AR", "stem": "During his senior year a high school football wide receiver was thrown 82 passes and caught 57\nof them.\nWhat is his reception percentage (what percentage of the passes thrown to him did he catch)?", "options": {"A": "30.4%", "B": "69.5%", "C": "43.8%", "D": "81.7%"}, "answer": "B", "answer_raw": "B", "explanation": "Multiply the number of caught passes by 100, then divide it by the number of passes thrown to\nthe receiver. The result will be the percentage.\n57 \u00d7 100 = 5700\n5700/82 = 69.5 = 69.5%", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 46, "excluded": false}, {"id": "AR-0124", "source_number": 124, "subtest": "AR", "stem": "Amanda has a 20-year term life insurance policy for $100,000. The annual premium is $ 12.00\nper thousand.\nHow much is her total premium payment every six months?", "options": {"A": "$600", "B": "$1,200", "C": "$100", "D": "$2,400"}, "answer": "A", "answer_raw": "A", "explanation": "There are 100 units of $1,000 in $100,000. Thus, Amanda pays 100 \u00d7 $12 (or $1,200) every\nyear in premiums, or $100 every month. Therefore, every six months, she pays 1/2 of $1,200 (or\nsix times $100), which equals $600.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 46, "excluded": false}, {"id": "AR-0125", "source_number": 125, "subtest": "AR", "stem": "If two pounds of salmon cost $13.98, what is the cost of five ounces of the same brand of\nsalmon?", "options": {"A": "$0.44", "B": "$0.87", "C": "$140", "D": "$2.20"}, "answer": "D", "answer_raw": "D", "explanation": "There are 16 ounces in one pound. Therefore, if two pounds of salmon cost $13.98, then one\npound costs $6.99. 1 ounce costs $6.99 \u00f7 16 = $0.44. 5 ounces cost $0.44 \u00d7 5 = $2.20", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 47, "excluded": false}, {"id": "AR-0126", "source_number": 126, "subtest": "AR", "stem": "If five SUV tires and four rims cost $1,730 and each rim costs $120, what is the cost of one tire?", "options": {"A": "$150.00", "B": "$220.60", "C": "$320.20", "D": "$250.00"}, "answer": "D", "answer_raw": "D", "explanation": "First, find the total cost of four rims:\n4 \u00d7 $120 = $480 Then, calculate the total cost of the five SUV tires:\n$1,730 (cost of tires and rims) - $480 (cost of rims) = $1,250 Finally, find the cost of one SUV\ntire:\n$1,250 \u00f7 5 = $250", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 47, "excluded": false}, {"id": "AR-0127", "source_number": 127, "subtest": "AR", "stem": "Calculate the volume of a semi-truck trailer that is 23 feet long, 15 feet wide, and 11 feet high.", "options": {"A": "2,530 sq ft", "B": "3,450 cu ft", "C": "3,795 sq ft", "D": "3,795 cu ft"}, "answer": "D", "answer_raw": "D", "explanation": "The formula for the volume of an object with parallel sides and right-angle comers is Length \u00d7\nWidth \u00d7 Height 23 feet of length \u00d7 15 feet of width \u00d7 11 feet of height = 3,795 cu ft (cubic feet)", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 47, "excluded": false}, {"id": "AR-0128", "source_number": 128, "subtest": "AR", "stem": "A college student spent $119 on tickets for family and friends to a sporting event.\nIf tickets were $7 and $10, and she bought an equal number of both kinds of tickets, how many\n$7 tickets did she buy?", "options": {"A": "4", "B": "5", "C": "7", "D": "11"}, "answer": "C", "answer_raw": "C", "explanation": "Let v be the number of tickets bought at each price (remember, the student bought the same\nnumber of both kinds of rickets).\nSo, 7v + 10v= 119\nNow combine the terms and continue solving the equation for v.\n17v =119\nv = 7", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 48, "excluded": false}, {"id": "AR-0129", "source_number": 129, "subtest": "AR", "stem": "Amanda earns an average of $22 an hour in tips as a waitress at the best steak restaurant in\ntown.\nIf her hourly wage is $2.50 and she has to pay a 10% tip share to the hostesses and busboys,\nhow much does she take home at the end of a day when she worked from 10:00 a.m. to 5:00\np.m.?", "options": {"A": "$32.90", "B": "$121.11", "C": "$138.60", "D": "$156.10"}, "answer": "D", "answer_raw": "D", "explanation": "First, calculate the amount of Amanda's hourly wages for a shift of 10:00 a.m. to 5:00 p.m.,\nwhich is seven hours.\n7 \u00d7 $2.50 = $17.50\nNext, calculate the amount of Amanda's tips for her seven-hour shift.\n7 \u00d7 $22 = $154\n\n\n\nNow, calculate the amount of her tips she has to share with the busboys and hostesses.\n$154 \u00d7 0.10 = $15.40\nNow add everything up.", "figure": "assets/figures/q0129.jpg", "passage_id": null, "topics": ["percentages_discount", "ratio_proportion", "averages"], "difficulty": 5, "flags": ["has_figure"], "page": 48, "excluded": false}, {"id": "AR-0130", "source_number": 130, "subtest": "AR", "stem": "During Friday night's high school performance of the play Seven Brides for Seven Brothers,\n76% of the seats in the performing arts center (with a seating capacity of 500 people) were\noccupied, and three-quarters of those attending were parents.\nHow many high school students attended the play?", "options": {"A": "95", "B": "100", "C": "76", "D": "285"}, "answer": "A", "answer_raw": "A", "explanation": "The first step is to calculate the number of total playgoers by multiplying the total seats available\nby the percentage.\n500 \u00d7 0.76 = 380\nSince three quarters (75%) of those attending were parents, that means that one quarter, or\n25%, were high school students; this is the answer we are going to calculate. Therefore,\nmultiply the number of total playgoers by the percentage of students to find out how many\nstudents attended the performance.\n380 \u00d7 0.25 = 95 students", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 49, "excluded": false}, {"id": "AR-0131", "source_number": 131, "subtest": "AR", "stem": "Jonathan spent four hours doing calculus problems, one hour playing Web-based video games,\nhalf an hour talking to his girlfriend, and two hours lifting weights and exercising.\nWhat percentage of his time was spent on math problems?", "options": {"A": "46.6%", "B": "50.0%", "C": "53.3%", "D": "57.1%"}, "answer": "C", "answer_raw": "C", "explanation": "Add all the blocks of rime together.\n4 + 1 + 0.5 + 2 = 7.5 hours total\nNow multiply the time spent doing calculus (four hours) by 100 and divide it by the total time to\nget the percentage of time spent:\n4 \u00d7 100 = 400\n400 \u00f7 7.5 = 53.3%", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 49, "excluded": false}, {"id": "AR-0132", "source_number": 132, "subtest": "AR", "stem": "Mrs. H.B. found a display model of a notebook computer to use for her business for $1,400,\nincluding software. However, since the model had been discontinued and the display had no\npackaging material or instructions, the store manager discounted the price to $1,150.\nWhat was the percentage of the reduction?", "options": {"A": "1.78%", "B": "13.0%", "C": "15.0%", "D": "17.9%"}, "answer": "D", "answer_raw": "D", "explanation": "Subtract the discounted price from the original price.\n$1,400 - $1,150 = $250\nNow multiply the amount of the discount by 100 and divide it by the original price.\n$250 \u00d7 100 = 25,000\n25,000 \u00f7 1,400= 17.857142 = 17.9% discount", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 50, "excluded": false}, {"id": "AR-0133", "source_number": 133, "subtest": "AR", "stem": "Heather bought a rectangular Persian rug with an outer perimeter measurement of 45 feet.\nIf the long sides measure 15 feet each, how long is each short side of the rug?", "options": {"A": "7.5 ft", "B": "10 ft", "C": "12.5 ft", "D": "15 ft"}, "answer": "A", "answer_raw": "A", "explanation": "The formula for the perimeter of a rectangle is P = 2L + 2W\nIf the long sides of the rug measure 15 feet each, then both long sides together equal 30 feet.\nSubtract the length of both long sides from the total perimeter measurement.\n45 - (2 \u00d7 15) = 45 -30 = 15ft\nNow we have the part of the perimeter made up by the short sides, but we need to divide it by\ntwo to get the length of each short side.\n15 ft \u00f7 2 = 7.5 ft", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 2, "flags": [], "page": 50, "excluded": false}, {"id": "AR-0134", "source_number": 134, "subtest": "AR", "stem": "In the circulation department of a city newspaper, four customer service representatives each\nreceive $320 a week, while two assistant managers earn $12 an hour each plus an average\n$100 per day commission.\nWhat is the average total weekly compensation paid to these six employees for a five-day, 40-\nhour work week?", "options": {"A": "$2,420", "B": "$3,240", "C": "$2,260", "D": "$4,520"}, "answer": "B", "answer_raw": "B", "explanation": "First, add up the wages made by the four customer service reps.\n$320 \u00d7 4 = $1,280\nNow calculate how much the two assistant managers make each week.\n2 assistant managers \u00d7 [($12 per hour \u00d7 40 hour) + (5 days per week \u00d7 $100)] = 2 assistant\nmanagers \u00d7 ($480 + $500)\n= 2 assistant managers \u00d7 $980 = $1,960 per week\nNow add the pay for the four customer service representatives to the pay for the two assistant\nmanagers.\n$1,280 + $1,960 = $3,240 total", "figure": null, "passage_id": null, "topics": ["percentages_discount", "averages"], "difficulty": 5, "flags": [], "page": 51, "excluded": false}, {"id": "AR-0135", "source_number": 135, "subtest": "AR", "stem": "Carpet costs $3 per square yard. The room that will be carpeted is 12 feet \u00d7 18 feet.\nHow much will the carpet cost?", "options": {"A": "$648", "B": "$216", "C": "$72", "D": "$324"}, "answer": "C", "answer_raw": "C", "explanation": "12 feet \u00d7 18 feet is equivalent to 4 yards \u00d7 6 yards = 24 square yards. 24 square yards \u00d7 $3 =\n$72. Remember 3 feet = 1 yard, but 9 sq feet = 1 sq yard.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "cost_profit"], "difficulty": 3, "flags": [], "page": 51, "excluded": false}, {"id": "AR-0136", "source_number": 136, "subtest": "AR", "stem": "If a train can travel 500 miles in five hours, how far can it travel in 15 minutes?", "options": {"A": "25 miles", "B": "30 miles", "C": "7 miles", "D": "125 miles"}, "answer": "A", "answer_raw": "A", "explanation": "First find the number of miles per hour the train travels.\nNow calculate how many miles the train travels in one minute.\n100 mph \u00f7 60 minutes = 1.67 miles per minute\nNow multiply the train's speed in miles per minute by the number of minutes in question.\n1.67 miles per minute \u00d7 15 minutes = 25 miles", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 1, "flags": [], "page": 51, "excluded": false}, {"id": "AR-0137", "source_number": 137, "subtest": "AR", "stem": "An employee of a chocolate factory earns $7.20 an hour. She is paid time and a half for\novertime beyond a 40- hour week.\nHow much will she earn in a week in which she works 43 hours?", "options": {"A": "$295.20", "B": "$320.40", "C": "$432.00", "D": "$464.40"}, "answer": "B", "answer_raw": "B", "explanation": "For the regular 40 hours, the worker earns $7.20 \u00d7 40 = $288.00. If the regular wage is $7.20\nper hour, then overtime paid at time and a half is $7.20 \u00d7 1.5 = $10.80. The three hours of\novertime earn the worker a total of $32.40. Add the regular time wages to the overtime wages:\n$288.00 + $32.40 = $320.40 total pay", "figure": null, "passage_id": null, "topics": ["work_rate"], "difficulty": 4, "flags": [], "page": 52, "excluded": false}, {"id": "AR-0138", "source_number": 138, "subtest": "AR", "stem": "A man died suddenly from a heart attack brought on by too much work and not enough\nexercise. Upon his death, his life insurance policies paid $750,000 to his wife and three children.\nThe policies were set up to pay the wife and children in the ratio of 5:1:1:1.\nHow much did the three children receive altogether?", "options": {"A": "$150,000", "B": "$200,000", "C": "$468,750", "D": "$281,250"}, "answer": "D", "answer_raw": "D", "explanation": "Start by letting* equal one share of the insurance money. According to the ratio, the wife\nreceived five shares (5x) and the children received one share (.v) a piece for a total of eight\nshares. Divide the total amount by the total number of shares.\n$750,000 \u00f7 8 = $93,750 per share\nNow multiply the amount of each share by the total number of shares received by the children.\n$93,750 \u00d7 3 = $281,250", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 5, "flags": [], "page": 52, "excluded": false}, {"id": "AR-0139", "source_number": 139, "subtest": "AR", "stem": "B Company (\"Bulldogs\"), 3rd Battalion, 144th Infantry, is authorized a total of 131 soldiers.\nHowever, Bulldog Company only has 125 total soldiers and officers assigned. Of those\nassigned, four percent are officers.\nHow many enlisted soldiers are assigned to the company?", "options": {"A": "114", "B": "123", "C": "120", "D": "121"}, "answer": "C", "answer_raw": "C", "explanation": "If four percent of the assigned strength of the unit are officers, then the percent of enlisted men\nis 100% - 4% = 96%\nTo find the number of enlisted men, multiply the total number assigned by 96% or 0.96.\n125 total soldiers \u00d7 0.96 = 120 enlisted soldiers", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 53, "excluded": false}, {"id": "AR-0140", "source_number": 140, "subtest": "AR", "stem": "A technology reseller purchasing agent procured 20 mid-brand DVD players for the listed\nwholesale price of $80 each, but receives a 25% discount because he is an established\ncustomer and friend of the wholesale dealer. His store then sells these DVD players at a 20%\nmarkup above the original wholesale price.\nWhat is the store's profit margin on each DVD player?", "options": {"A": "$16", "B": "$72", "C": "$20", "D": "$36"}, "answer": "D", "answer_raw": "D", "explanation": "The first step in solving this problem is to find the discount received from the wholesale dealer\nfor cadi DVD player by multiplying the listed price by the discount percentage:\n$80 \u00d7 0.25 = $20\nNext, find the actual price per DVD player paid to the wholesale dealer:\n$80 - $20 = $60\nNow find the retail margin by multiplying the markup percentage by the original wholesale price:\n$80 \u00d7 0.20 = $16\nNext, find the retail price for which the technology store sells the DVD players to its customers\nby adding the markup amount to the listed wholesale amount:\n$80 + $16 = $96\nTo find the profit margin, subtract the retail price from the actual price paid to the wholesale\ndealer.\n$96 - $60 = $36 profit per DVD player", "figure": null, "passage_id": null, "topics": ["percentages_discount", "cost_profit"], "difficulty": 5, "flags": [], "page": 53, "excluded": false}, {"id": "AR-0141", "source_number": 141, "subtest": "AR", "stem": "A special-purpose cartographer (mapmaker) receives an order requiring a customized map with\na scale of one inch = 50 miles.\nIf the actual straight-line ground distance between two points is 120 miles, how far apart should\nthe cartographer show them on the map?", "options": {"A": "0.4 inches", "B": "2.4 inches", "C": "1.2 inches", "D": "4.8 inches"}, "answer": "B", "answer_raw": "B", "explanation": "Since one inch on the map represents 50 miles, divide the ground distance (120 miles) by the\nscale (50 miles to the inch) to find the number of inches needed to represent 120 miles.\n120 \u00f7 50 = 2.4", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 4, "flags": [], "page": 54, "excluded": false}, {"id": "AR-0142", "source_number": 142, "subtest": "AR", "stem": "In Hendricks on Township, houses are assessed at 80% of the purchase price.\nIf Mr. Thomas buys a house in Hendricks on for $120,000 and rea estate taxes are $4.75 per\n$100 of assessed valuation, how much property tax must he pay per year?", "options": {"A": "$3,648", "B": "$5,472", "C": "$4,560", "D": "$4,845"}, "answer": "C", "answer_raw": "C", "explanation": "Multiply the purchase price of the home by the assessment rate to find the assessed value.\n120,000 \u00d7 0.8 = $96,000 (assessed value)\nFind the number of hundreds in the assessed value.\n$96,000 \u00f7 100 = 960 (hundreds)\nMultiply the number of hundreds by the tax rate.\n960 \u00d7 $4.75 = $4,560 (property tax)", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 5, "flags": [], "page": 54, "excluded": false}, {"id": "AR-0143", "source_number": 143, "subtest": "AR", "stem": "The fuel tank of a gasoline generator holds enough fuel to operate the generator for one hour\nand 15 minutes.\nAbout how many times must the fuel tank be filled to run the generator from 6:15 p.m. to 7:00\na.m.?", "options": {"A": "9.4", "B": "10.2", "C": "10.8", "D": "11.5"}, "answer": "B", "answer_raw": "B", "explanation": "First find the total time needed to run the generator = 12 hours and 45 minutes or 12.75\nminutes. Now divide the total time needed to run the generator by the amount of rime each tank\nof fuel will last.\n12.75 / 1.25 = 10.2 tanks of fuel", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 4, "flags": [], "page": 54, "excluded": false}, {"id": "AR-0144", "source_number": 144, "subtest": "AR", "stem": "When Highway 2011 was converted from toll-free to a toll road, the traffic density per day\ndeclined from 11,200 vehicles to 10,044.\nWhat was the percentage decline in traffic?", "options": {"A": "10.3%", "B": "0.5%", "C": "10.1%", "D": "8.9%"}, "answer": "A", "answer_raw": "A", "explanation": "First find the amount of the decline in traffic. 11,200 cars - 10,044 cars = 1,156 fewer cars per\nday. Now multiply the amount of traffic decrease by 100 and then divide it by the amount of\noriginal traffic. This will yield the percentage decrease without further calculation.\n1,156 \u00d7 100 = 115,600\n115,600 \u00f7 11,200 = 10.3% decrease", "figure": null, "passage_id": null, "topics": ["percentages_discount", "unit_conversion"], "difficulty": 4, "flags": [], "page": 55, "excluded": false}, {"id": "AR-0145", "source_number": 145, "subtest": "AR", "stem": "June drove for two hours at an average speed of 70 miles per hour, then drove another 90\nminutes at an average speed of 65 miles per hour.\nIf her vehicle gets 25 miles per gallon on the highway in this speed range, about how many\ngallons of gas did she use for the trip?", "options": {"A": "5.4 gallons", "B": "8.2 gallons", "C": "8.4 gallons", "D": "9.5 gallons"}, "answer": "D", "answer_raw": "D", "explanation": "First calculate the distances driven during the two legs of the trip.\nLeg 1: 2 hours \u00d7 70 mph = 140 miles\nLeg 2: 1.5 hours \u00d7 65 mph = 97.5 miles\n140 miles + 97.5 miles = 237.5 miles\nNow divide the total distance traveled by the car's gas mileage rate.\n237.5 miles 4 \u00f7 25 mpg = 9.5 gallons", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate", "unit_conversion"], "difficulty": 4, "flags": [], "page": 55, "excluded": false}, {"id": "AR-0146", "source_number": 146, "subtest": "AR", "stem": "Jonathan earns $350 before taxes every two weeks at his part-time job. His withholdings are\n$27.75 for federal income taxes, $5.65 for Social Security (FICA), and $12.87 for Medicare tax.\nHow much will his net paycheck be?", "options": {"A": "$314.73", "B": "$304.73", "C": "$303.73", "D": "$313.73"}, "answer": "C", "answer_raw": "C", "explanation": "First, total up all the withholding amounts.\n$27.75 + $5.65 + $12.87 = $46.27\nJonathan's net pay is his salary for the pay period minus the total of all the withholdings.\nNet pay = $350.00 - $46.27 = $303.73", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 56, "excluded": false}, {"id": "AR-0147", "source_number": 147, "subtest": "AR", "stem": "A training certificate composed on a personal computer that was designed to be nine inches\nlong and six inches wide has to be proportionately enlarged so that its length will be 12 inches.\nHow many inches wide will the enlarged certificate be?", "options": {"A": "8", "B": "6", "C": "9", "D": "10"}, "answer": "C", "answer_raw": "C", "explanation": "Since the certificate and its enlargement are similar (i.e., proportional) figures, the lengths will\nhave the same ratio as the widths; if the length is increased by a given proportion, then the\nwidth will be increased by the same proportion or percentage of its original size.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "ratio_proportion"], "difficulty": 2, "flags": [], "page": 56, "excluded": false}, {"id": "AR-0148", "source_number": 148, "subtest": "AR", "stem": "A basketball team won 70% of the 40 games it played.\nHow many games did it lose?", "options": {"A": "28", "B": "30", "C": "22", "D": "12"}, "answer": "D", "answer_raw": "D", "explanation": "To find the number of games won, multiply the number of games played, 40, by 70% or, put\ndifferently, 0.7.\n\n\n\n40 \u00d7 0.7 = 28\nThe number of games lost is the total number played minus the number won.\nNumber of games lost = 40 - 28 = 12", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 56, "excluded": false}, {"id": "AR-0149", "source_number": 149, "subtest": "AR", "stem": "The two members of Hoosiephaffer LLC, a limited liability company, operate their business such\nthat it shows a profit for the year of $63,000. Their LLC operating agreement calls for them to\nshare the profits in the ratio 5:4.\nHow much of the profit should go to the member who gets the larger share?", "options": {"A": "$35,000", "B": "$28,000", "C": "$32,000", "D": "$36,000"}, "answer": "A", "answer_raw": "A", "explanation": "If the profits are shared in the ratio 5:4, one partner gets 5/9 of the profits and the other gets 4/9.\nNote that 5/9 +\n4/9 = 1, the whole profit. The larger share is 5/9 of the profit, $35,000.", "figure": null, "passage_id": null, "topics": ["ratio_proportion", "cost_profit"], "difficulty": 4, "flags": [], "page": 57, "excluded": false}, {"id": "AR-0150", "source_number": 150, "subtest": "AR", "stem": "A corporate purchaser paid $17.16 for an item that had recently been increased in price by the\nwholesaler by four percent.\nWhat was the price of the item before the increase?", "options": {"A": "$17.00", "B": "$17.12", "C": "$16.50", "D": "$16.47"}, "answer": "C", "answer_raw": "C", "explanation": "Consider the original price as 100%. Then the price after an increase of 4% is 104%. To find the\noriginal price, divide the price after the increase, $17.16, by 104% (or 1.04).\n$17.16 \u00f7 1.04 = $16.50\n$16.50 = original price", "figure": null, "passage_id": null, "topics": ["percentages_discount", "cost_profit"], "difficulty": 2, "flags": [], "page": 57, "excluded": false}, {"id": "AR-0151", "source_number": 151, "subtest": "AR", "stem": "A fire team is made up of four junior enlisted men and one noncommissioned officer as the team\nleader. A group of 64 privates fresh from basic training is to be divided into fire teams.\nHow many team leaders will be needed?", "options": {"A": "8", "B": "10", "C": "12", "D": "16"}, "answer": "D", "answer_raw": "D", "explanation": "The number of privates in the group who have just graduated from basic training divided by the\nnumber in each fire team gives you the number of fire teams and therefore the number of team\nleaders needed.\n64 \u00f7 4=16\n16 team leaders are needed, one for each position.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 57, "excluded": false}, {"id": "AR-0152", "source_number": 152, "subtest": "AR", "stem": "A tree 36 feet high casts a shadow 8 feet long. At the same time, another tree casts a shadow 6\nfeet long.\nHow tall is the second tree?", "options": {"A": "30 feet", "B": "27 feet", "C": "24 feet", "D": "32 feet"}, "answer": "B", "answer_raw": "B", "explanation": "The ratio of the heights of the two trees will be the same as the ratio of the lengths of their\nshadows. The ratio of the length of the shadow of the second tree to the length of the shadow of\nthe first tree is 6/8 or 3/4.\nThus, the height of the second tree is 3/4 of the height of the 36 feet tree.\n3/4 \u00d7 36/1 = 27/1 = 27 feet", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 58, "excluded": false}, {"id": "AR-0153", "source_number": 153, "subtest": "AR", "stem": "Temperature readings on a certain day ranged from a low of -4\u00b0F to a high of 16\u00b0F.\nWhat was the average temperature for the day?", "options": {"A": "10\u00b0F", "B": "6\u00b0F", "C": "12\u00b0F", "D": "8\u00b0F"}, "answer": "B", "answer_raw": "B", "explanation": "The average is the sum of the high and low temperatures divided by 2.\nAverage = (-4\u00b0+16\u00b0) / 2 = 12\u00b0 / 2 = 6\u00b0", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 2, "flags": [], "page": 58, "excluded": false}, {"id": "AR-0154", "source_number": 154, "subtest": "AR", "stem": "A plane left San Francisco at 6:15 pm PST and arrived in Philadelphia at 2:45 am EST.\nHow long was the flight?", "options": {"A": "81/2 hours", "B": "51/2 hours", "C": "61/2 hour", "D": "91/2 hours"}, "answer": "B", "answer_raw": "B", "explanation": "First, convert 6:15 PST to 9:15 EST. The flight then took from 9:15 pm EST to 2:45 am EST.\nThat means that the flight took 51/2 hours.", "figure": null, "passage_id": null, "topics": ["ratio_proportion", "rate_time_distance"], "difficulty": 2, "flags": [], "page": 58, "excluded": false}, {"id": "AR-0155", "source_number": 155, "subtest": "AR", "stem": "An automobile manufacturer offers a 15% rebate on the list price of a new car.\nWhat would be the rebate on a car that lists for $13,620?", "options": {"A": "$900.00", "B": "$11,577.00", "C": "$204.30", "D": "$2,043.00"}, "answer": "D", "answer_raw": "D", "explanation": "The rebate will be 15% (or 0.15) of the list price, $13,600.\n$13,620 \u00d7 0.15 = $2,043.00 = rebate", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 59, "excluded": false}, {"id": "AR-0156", "source_number": 156, "subtest": "AR", "stem": "A toll is $2 for a car and the driver and 75 cent for each additional passenger.\nIf the toll comes to $4.25, how many total people are in the car?", "options": {"A": "6", "B": "5", "C": "3", "D": "4"}, "answer": "D", "answer_raw": "D", "explanation": "The toll of $4.25 includes $2 for the driver/car. So $2.25 ($4.25 - $2) is left for the passengers.\n$2.25 / 0.75 = 3 passengers, so the total amount of people in the car is 1 driver and 3\npassengers.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 59, "excluded": false}, {"id": "AR-0157", "source_number": 157, "subtest": "AR", "stem": "A night watchman is required to check in every 40 minutes while making his rounds, to list tour\nof duty extends from 9:00 P.M. to 5:00 A.M.\nIf he checks in at the start of his rounds and also when lie finishes, how many times does he\ncheck in during the night?", "options": {"A": "12", "B": "13", "C": "8", "D": "20"}, "answer": "B", "answer_raw": "B", "explanation": "From 9:00 P.M. to 5:00 A.M. is a tour of duty of 8 hours. Since 60 minutes = 1 hour, when the\nwatchman checks in every 40 minutes he checks in every 40/60, or every 2/3, of an hour.\n8/1 \u00f7 2/3 = 8/1 \u00d7 3/2 = 12\nThe watchman must check in once at the beginning of each of the twelve 40-minute periods, or\n12 times. But he must also check in at the end of the last period. Thus, he checks in 12 + 1, or\n13, times.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 4, "flags": [], "page": 59, "excluded": false}, {"id": "AR-0158", "source_number": 158, "subtest": "AR", "stem": "A flight is scheduled for departure at 3:50 P.M.\nIf the flight takes 2 hours and 55 minutes, at what time is it scheduled to arrive at its destination?", "options": {"A": "5:05 P.M.", "B": "6:05 P.M.", "C": "6:15 P.M.", "D": "6:45 P.M."}, "answer": "D", "answer_raw": "D", "explanation": "The time of arrival is 2 hours and 55 minutes after the departure time of 3:50 P.M. By 4:00 P.M.,\nthe flight has taken 10 minutes of the total flight time of 2 hours and 55 minutes. 2 hours and 45\nminutes remain, and 2 hours and 45 minutes after 4:00 P.M. is 6:45 P.M.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 3, "flags": [], "page": 60, "excluded": false}, {"id": "AR-0159", "source_number": 159, "subtest": "AR", "stem": "How many 4-ounce candy bars are there in a 3-pound package of candy?", "options": {"A": "12", "B": "16", "C": "48", "D": "9"}, "answer": "A", "answer_raw": "A", "explanation": "There are 16 ounces in 1 pound. Therefore, 4 of the 4-ounce candy bars will make 1 pound. A\n3-pound package will hold 3 times 4 or 12 bars.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 2, "flags": [], "page": 60, "excluded": false}, {"id": "AR-0160", "source_number": 160, "subtest": "AR", "stem": "In a restaurant, a diner orders an entree with vegetables for $10.50, dessert for $1.50, and\n\n\n\ncoffee for $0.50.\nIf the tax on meals is 6%, what tax should be added to his check?", "options": {"A": "$0.06", "B": "$0.63", "C": "$0.72", "D": "$0.75"}, "answer": "D", "answer_raw": "D", "explanation": "First add the prices of the three items ordered to get the cost of the meal before the tax. $10.50\n+ $1.50 + $.50 = $12.50. The taxis 6% (or 0.06) of the cost of the meal. 0.06 \u00d7 $12.50 = $0.75", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 60, "excluded": false}, {"id": "AR-0161", "source_number": 161, "subtest": "AR", "stem": "A 55-gallon drum of oil is going to be used to fill cans that hold 2 quarts each.\nHow many cans can be filled from the drum?", "options": {"A": "55", "B": "27", "C": "110", "D": "220"}, "answer": "C", "answer_raw": "C", "explanation": "There are 4 quarts in 1 gallon. A 55-gallon drum holds 4 \u00d7 55 quarts.\n4 \u00d7 455 quarts = 220 quarts. If each can holds 2 quarts, the number of cans filled is 220 divided\nby 2.\n220 / 2 = 110 cans", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 2, "flags": [], "page": 61, "excluded": false}, {"id": "AR-0162", "source_number": 162, "subtest": "AR", "stem": "In a factory that makes wooden spindles, a lathe operator takes 45 minutes to do the finishing\nwork on nine spindles.\nHow many hours will it take him to finish 96 spindles at the same rate?", "options": {"A": "8", "B": "72", "C": "100", "D": "10"}, "answer": "A", "answer_raw": "A", "explanation": "The number of minutes required to finish 1 spindle is the number of minutes, 45, taken for all 9\nspindles, divided by their number, 9.\n45 / 9 = 5 minutes per spindle. The number of minutes to finish 96 spindles will be 96 times as\nmuch. 5 \u00d7 96 = 480 minutes There are 60 minutes in 1 hour. Divide the number of minutes by\n60 to convert their number to hours.\n\n\n\n480 / 60 = 8 hours", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 61, "excluded": false}, {"id": "AR-0163", "source_number": 163, "subtest": "AR", "stem": "A triangle has two equal sides. The third side has a length of 13 feet, 2 inches.\nIf the perimeter of the triangle is 40 feet, what is the length of one of the equal sides?", "options": {"A": "13 feet, 4 inches", "B": "26 feet, 10 inches", "C": "13 feet, 11 inches", "D": "13 feet, 5 inches"}, "answer": "D", "answer_raw": "D", "explanation": "The perimeter, 40 feet, is the sum of the lengths of all three sides. The sum of the lengths of the\ntwo equal sides is the difference between the perimeter and the length of the third side. Sum of\nlengths of 2 equal sides = 40 feet - 13 feet, 2 inches = 39 feet, 12 inches - 13 feet, 2 inches = 26\nfeet, 10 inches. The length of one side is obtained by dividing the sum by 2. Length of one equal\nside: 26 feet, 10 inches / 2 = 13 feet, 5 inches", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 62, "excluded": false}, {"id": "AR-0164", "source_number": 164, "subtest": "AR", "stem": "A lawn is 21 feet wide and 39 feet long.\nHow much will it cost to weed and feed it if a gardening service charges $0.40 per square yard\nfor this treatment?", "options": {"A": "$109.20", "B": "$36.40", "C": "$327.60", "D": "$24.00"}, "answer": "B", "answer_raw": "B", "explanation": "Since 3 feet = 1 yard, convert the length and width to yards by dividing their dimensions in feet\nby 3.\nWidth = 39/3 = 7 yards;\n39 length = 39/3 = 13 yards\nThe area of a rectangle is the product of its length and width.\nArea = 7 \u00d7 13 = 91 square yards. The cost for the entire lawn is obtained by multiplying the area\nin square yards by the cost per square yard.\n91 \u00d7 $.40 = $36.40", "figure": null, "passage_id": null, "topics": ["unit_conversion", "cost_profit"], "difficulty": 3, "flags": [], "page": 62, "excluded": false}, {"id": "AR-0165", "source_number": 165, "subtest": "AR", "stem": "A bonded courier drove for 7 hours on back roads at an average speed of 48 miles per hour.\nHer car gets 21 miles per gallon of gas.\nHow many gallons of gas did she use?", "options": {"A": "24", "B": "11", "C": "18", "D": "16"}, "answer": "D", "answer_raw": "D", "explanation": "Find the number of miles traveled by multiplying the rate, 48 miles per hour, by the time, 7\nhours.\n48 \u00d7 7 = 336 miles\nThe number of gallons of gas used is the number of miles driven divided by the number of miles\nper gallon.\n336 / 21 = 112 / 7 = 16 gallons", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "unit_conversion", "work_rate"], "difficulty": 4, "flags": [], "page": 62, "excluded": false}, {"id": "AR-0166", "source_number": 166, "subtest": "AR", "stem": "A wall is 7 feet 8 inches in height; four vertical pieces of wallpaper are needed to cover the wall.\nAssuming there is no waste, what is the minimum length that a roll of wallpaper must be to\ncover the wall?", "options": {"A": "29 feet, 2 inches", "B": "31 feet, 2 inches", "C": "31 feet", "D": "30 feet, 8 inches"}, "answer": "D", "answer_raw": "D", "explanation": "If there are four pieces of wallpaper, each 7 feet, 8 inches long, the total length of the wallpaper\nis 4 \u00d7 7 feet, 8 inches, or 28 feet, 32 inches. Since 12 inches = 1 foot, 32 inches = 2 feet, 8\ninches. Thus, 28 feet, 32 inches = 30 feet, 8 inches.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 63, "excluded": false}, {"id": "AR-0167", "source_number": 167, "subtest": "AR", "stem": "We bought 5 pounds of cashew nuts worth $1.80 per pound, mixed with 4 pounds of peanuts\nworth $1.62 per pound.\nWhat is the value per pound of the mixture?", "options": {"A": "$1.72", "B": "$1.71", "C": "$3.42", "D": "$l.82"}, "answer": "A", "answer_raw": "A", "explanation": "5 pounds of cashew nuts at $1.80 per pound is worth 5 \u00d7 $1.80 = $9.00 4 pounds of peanuts at\n$1.62 per pound is worth 4 \u00d7 $1.62 = $6.48.\nThe total value of the 9-pound mixture is $9.00 + $6.48 = $15.48. The value of the mixture per\npound is found by dividing the total value by the number of pounds.\n$15.48 / 9 = $1.72", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 63, "excluded": false}, {"id": "AR-0168", "source_number": 168, "subtest": "AR", "stem": "In a clothing factory, 5 workers finish production of 6 garments each per day, 3 others turn out 4\ngarments each per day, and 1 worker turns out 12 per day.\nWhat is the average number of garments produced per worker per day?", "options": {"A": "22/9", "B": "6", "C": "4", "D": "71/3"}, "answer": "B", "answer_raw": "B", "explanation": "5 workers making 6 garments each = 30 garments per day\n3 workers making 4 garments each = 12 garments per day\n1/9 workers making 12 garments = 12/54 garments per day\nAdd the number of workers and the number of garments per day.\n9 workers make 54 garments per day.\nTo find the average number of garments per worker per day, divide the number of garments per\nday by the number of workers.\n54/9 = 6 garments per worker per day.", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 5, "flags": ["explanation_may_belong_to_next"], "page": 64, "excluded": false}, {"id": "AR-0169", "source_number": 169, "subtest": "AR", "stem": "A man makes a 255-mile trip by car. He drives the first 2 hours at 45 miles per hour.\nAt what speed must he then travel for the remainder of the trip in order to arrive at his\ndestination 5 hours after he started?", "options": {"A": "31 miles per hour", "B": "50 miles per hour", "C": "51 miles per hour", "D": "55 miles per hour"}, "answer": "D", "answer_raw": "D", "explanation": "The distance traveled by driving at 45 mph for 2 hours is 2 \u00d7 45, or 90 miles.\nThe remainder of the 255 mile trip is 255 - 90, or 165 miles.\nTo finish the trip in 5 hours, the man has 5 - 2, or 3, hours still to drive.\nTo find the rate of travel for a distance of 165 miles driven in 3 hours, divide the distance by the\ntime.\n165/3 = 55 miles per hour", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 5, "flags": [], "page": 64, "excluded": false}, {"id": "AR-0170", "source_number": 170, "subtest": "AR", "stem": "A contractor bids $300,000 as her price for erecting a building. She estimates that 1/10 of this\namount will be spent for masonry materials and labor, 1/3 for lumber and carpentry, 1/5 for\nplumbing and heating, and 1/6 for electrical and lighting work. The balance will be her profit.\nHow much profit does she expect to make?", "options": {"A": "$24,000", "B": "$80,000", "C": "$60,000", "D": "$50,000"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 5, "flags": [], "page": 64, "excluded": false}, {"id": "AR-0171", "source_number": 171, "subtest": "AR", "stem": "The list price of a TV set is $325, but the retailer offers successive discounts of 20% and 30%.\nWhat price does a customer actually pay?", "options": {"A": "$182.00", "B": "$270.00", "C": "$162.50", "D": "$176.67"}, "answer": "A", "answer_raw": "A", "explanation": "The first discount of 20% means that a customer actually pays 80% (or 4/5) of the list price. The\nsecond successive discount of 30% means that a customer actually pays 70% (or 3/10) of the\nprice determined after the first discount.\nThe price the customer actually pays is the list price multiplied by the portions determined from\neach discount.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "cost_profit"], "difficulty": 2, "flags": [], "page": 65, "excluded": false}, {"id": "AR-0172", "source_number": 172, "subtest": "AR", "stem": "A certain brand of motor oil is regularly sold at a price of two cans holding a quart each for\n$1.99. On a special sale, a carton containing six quart cans is sold for $5.43.\nWhat is the saving per quart if the oil is bought at the special sale price?", "options": {"A": "$0.27", "B": "$0.09", "C": "$0.54", "D": "$0.541/4"}, "answer": "B", "answer_raw": "B", "explanation": "At 2 quarts for $1.99, each quart costs $0.995. At 6 quarts for $5.43, each quart costs $0.905.\n$0.995 - $0.905 = $0.905", "figure": null, "passage_id": null, "topics": ["percentages_discount", "unit_conversion"], "difficulty": 3, "flags": [], "page": 65, "excluded": false}, {"id": "AR-0173", "source_number": 173, "subtest": "AR", "stem": "A company spends 3/5 of its advertising budget on newspaper ads and 1/3 on radio\ncommercials.\nWhat portion of the advertising budget is left for TV commercials?", "options": {"A": "1/2", "B": "7/30", "C": "1/15", "D": "1/8"}, "answer": "C", "answer_raw": "C", "explanation": "Add the portion spent on newspaper ads and radio commercials.\n3/5 + 1/3 = 9/15 + 5/15 = 14/15.\nThe portion left for TV commercials is the entire budget, 1, minus portion spent on newspaper\nand radio 14/15.\n1 - 14/15 = 15/15 - 14/15 = 1/15", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 65, "excluded": false}, {"id": "AR-0174", "source_number": 174, "subtest": "AR", "stem": "At Joe's Restaurant, one-fourth of the patrons are male and one-fifth of the patrons are from out\nof town.\nWhat proportion would you expect to be male and out of town?", "options": {"A": "1/5", "B": "1/10", "C": "1/20", "D": "1/25 E. 1/50"}, "answer": "C", "answer_raw": "C", "explanation": "If one-fourth of the patrons are male, then you would expect one-fourth of the out-of-town\npatrons to be male.\nOne fourth of one-fifth is 1/20.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 2, "flags": [], "page": 66, "excluded": false}, {"id": "AR-0175", "source_number": 175, "subtest": "AR", "stem": "There are 112 males and 78 females working at a hospital.\nWhat percentage of the hospitals workforce is female?", "options": {"A": "22%", "B": "32%", "C": "38%", "D": "41% E. 78%"}, "answer": "D", "answer_raw": "D", "explanation": "Add the number of men and women to get the total number: 190. The number of women, 78, so\ndivide 78 by 190 (78/190) to get 0.4105. Then multiply by 100 to convert it to a percentage and\nyou have 41%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 66, "excluded": false}, {"id": "AR-0177", "source_number": 177, "subtest": "AR", "stem": "If a patient doesn't receive treatment for a certain injury within 2 hours after injury, the patient's\nchance of survival starts decreasing by 15% each hour.\nIf no treatment has been given within 4 hours after injury, roughly, what chance of survival will\nthe patient have?", "options": {"A": "70%", "B": "72%", "C": "75%", "D": "77% E. 80%"}, "answer": "B", "answer_raw": "B", "explanation": "At the end of two hours, the patient still has a 100% chance of survival. After three hours, he\nhas an 85% of survival, or 0.85. After four hours, he has an 85% of the 85% he had at the end\nof three hours: 0.85 \u00d7 0.85 = 72.25% chance of survival.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "basic_probability"], "difficulty": 4, "flags": [], "page": 67, "excluded": false}, {"id": "AR-0178", "source_number": 178, "subtest": "AR", "stem": "William is from England and is visiting the United States. On his trip he visits Texas and notices\nthat it is very hot. He looks at a thermometer and it reads 95 degrees Fahrenheit.\nWilliam wants to know what this converts to in Celsius? Assume C = (F - 32) / 1.8", "options": {"A": "30 degrees C", "B": "35 degrees C", "C": "40 degrees C", "D": "45 degrees C E. 50 degrees C"}, "answer": "B", "answer_raw": "B", "explanation": "Substituting 95 for F in the equation yields C = (95 - 32) = 63 / 1.8 = 35 degrees C.", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 5, "flags": [], "page": 67, "excluded": false}, {"id": "AR-0179", "source_number": 179, "subtest": "AR", "stem": "A student scores 74, 87, 68, 63, 76 on his last five exams. His teacher will drop the lowest grade\nto compute the student's average.\nWhat is the students average in the class?", "options": {"A": "76.3%", "B": "79.4%", "C": "84.9%", "D": "89.4% E. 68.2%"}, "answer": "A", "answer_raw": "A", "explanation": "The teacher will drop the 63, and only count the four best scores. These are 74, 87, 68, and 76.\nTo find the average, add the 4 numbers and divide the sum by 4.", "figure": null, "passage_id": null, "topics": ["percentages_discount", "averages"], "difficulty": 3, "flags": [], "page": 68, "excluded": false}, {"id": "AR-0180", "source_number": 180, "subtest": "AR", "stem": "21/4 + 63/8 = __________.", "options": {"A": "8", "B": "83/8", "C": "85/8", "D": "9"}, "answer": "C", "answer_raw": "C", "explanation": "Convert the 1/4 to 2/8 and then add 2/8 to 3/8 to get 5/8. Finally add 6 + 2 and you have 85/8", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 68, "excluded": false}, {"id": "AR-0181", "source_number": 181, "subtest": "AR", "stem": "A world map has a scale of 1/4 of an inch equals 250 miles. You measure the distance between\nNew York, NY and Los Angeles, California and it equals 3 inches.\nWhat is the real distance between New York and LA?", "options": {"A": "2,500 miles", "B": "2,750 miles", "C": "2,800 miles", "D": "3,000 miles E. 3,250 miles"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 4, "flags": [], "page": 68, "excluded": false}, {"id": "AR-0182", "source_number": 182, "subtest": "AR", "stem": "Of 1,000 dogs, 72% are male. Among the males, 3 out of 5 were over the age 5.\nHow many of the dogs were males over the age of 5?", "options": {"A": "312", "B": "432", "C": "468", "D": "512 E. 720"}, "answer": "B", "answer_raw": "B", "explanation": "First multiply 1000 \u00d7 0.72 to find out how many dogs are male. This results in 720 male dogs of\nwhich 3/5 are over the age of 5. Therefore, multiply 720 \u00d7 3/5 (or 0.6) which results in 432.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 68, "excluded": false}, {"id": "AR-0183", "source_number": 183, "subtest": "AR", "stem": "There are 78 female and 54 male patrons at a local diner.\nWhat percentage of the diner's patrons are female?", "options": {"A": "37%", "B": "41%", "C": "52%", "D": "59% E. 67%"}, "answer": "D", "answer_raw": "D", "explanation": "Add 78 to 54 to get 132 total patrons, then divide the number of females into the total number of\npatrons.\nTherefore, 78/132 = 0.5909 = 59%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 69, "excluded": false}, {"id": "AR-0184", "source_number": 184, "subtest": "AR", "stem": "A new cancer treatment provides a 50% success rate for patients with lung tumors. Lung tumors\nmake up 10% of all cancer patients.\nWhat percentage of all cancer patients will this new drug work on?", "options": {"A": "5%", "B": "20%", "C": "50%", "D": "80% E. 95%"}, "answer": "A", "answer_raw": "A", "explanation": "A simple way to solve this is to multiply the two percentages. Therefore, multiply 0.50 \u00d7 0.10\nand you get 0.05 or 5%.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 69, "excluded": false}, {"id": "AR-0185", "source_number": 185, "subtest": "AR", "stem": "A person who has a heart attack can be saved 90% of the time if a defibrillator is used within 5\nminutes of the heart attack. Of the people that have heart attacks, defibrillators are within the\nvicinity 40% of the time; however, they are only used 60% of the time even when they are in the\nsurrounding area.\nHow many people who suffer a heart attack are saved because of the use of a defibrillator?", "options": {"A": "18%", "B": "22%", "C": "40%", "D": "54% E. 60%"}, "answer": "B", "answer_raw": "B", "explanation": "If a defibrillator is used, we know that the patient will have a 90% success rate; however, only\n40% of the people have this option available.\nTherefore, we take 0.9 \u00d7 0.4 and know that only 36% of the people have this opportunity.\nHowever, we also know that of the 36% of suffers, only 60% of the time is a defibrillator used.\nTherefore, we must take 0.6 \u00d7 0.36 to find out how many patients are saved by the use of a\ndefibrillator.\nThis results in 0.216 or 22% of patients are saved by the use of a defibrillator.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 5, "flags": [], "page": 69, "excluded": false}, {"id": "AR-0186", "source_number": 186, "subtest": "AR", "stem": "A paint company mixes its paint with water to create more paint per gallon. They currently have\nten gallon jugs which contain 10% water.\nHow much water must they add to create an 80/20 mix of paint to water?", "options": {"A": "1 gallon", "B": "1.25 gallons", "C": "1.5 gallons", "D": "1.75 gallons E. 2 gallons"}, "answer": "B", "answer_raw": "B", "explanation": "Currently the mixture is 90% paint, 10% water or 9 gallons of paint for every 1 gallon of water.\nFor the company to create an 80% / 20% mix, the company must add 1.25 gallons to their\ncurrent 10 gallon mixtures. This will create 2.25 gallons of water for every 11.25 total gallons.\nThis results in a 2.25/11.25 or 20% water mix.", "figure": null, "passage_id": null, "topics": ["unit_conversion", "percentages_discount"], "difficulty": 4, "flags": [], "page": 70, "excluded": false}, {"id": "AR-0187", "source_number": 187, "subtest": "AR", "stem": "A mail carrier can deliver mail to 1,400 different homes in one day. In the city of Utopia, there\nare 52,800 residents.\nHow many mail carriers must be hired to deliver mail to all of the residents of Utopia each day?", "options": {"A": "38", "B": "43", "C": "48", "D": "54 E. 60"}, "answer": "A", "answer_raw": "A", "explanation": "To find the number of required mail carriers, simply divide 52,800 by 1,400 to get 37.714.\nTherefore, you must round up and you have 38 mail carriers.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 70, "excluded": false}, {"id": "AR-0188", "source_number": 188, "subtest": "AR", "stem": "How much change would you get back from a $100.00 bill if you purchased eight DVDs costing\n$6.49 each?", "options": {"A": "$24.24", "B": "$48.08", "C": "$51.92", "D": "$64.90"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 71, "excluded": false}, {"id": "AR-0189", "source_number": 189, "subtest": "AR", "stem": "Fencing costs $1.50 per picket. 2 pickets are used per foot. Posts cost $13.75 per post.\nHow much will it cost to fence a yard if 10 posts and 46 feet of pickets are needed?", "options": {"A": "$125.50", "B": "$138.00", "C": "$275.50", "D": "$380.75"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": [], "page": 71, "excluded": false}, {"id": "AR-0190", "source_number": 190, "subtest": "AR", "stem": "Louis ran a race in 2.4 minutes. Laura ran the same race in 124 seconds.\nWhat is the difference between the two times?", "options": {"A": "2 seconds", "B": "20 seconds", "C": "40 seconds", "D": "1 minute"}, "answer": "B", "answer_raw": "B", "explanation": "2.4 minutes is 144 seconds", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 71, "excluded": false}, {"id": "AR-0191", "source_number": 191, "subtest": "AR", "stem": "A grocery store has a special on sodas. Three 12 packs for $9.00.\nHow much does five 12 packs of soda cost?", "options": {"A": "$9.00", "B": "$12.00", "C": "$15.00", "D": "$18.00"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": [], "page": 71, "excluded": false}, {"id": "AR-0192", "source_number": 192, "subtest": "AR", "stem": "A family of four have a dinner bill for $44.00. A 15% tip is added after an 8% tax is added to the\namount.\nHow much is the tip?", "options": {"A": "$4.05", "B": "$6.60", "C": "$6.71", "D": "$7.13"}, "answer": "D", "answer_raw": "D", "explanation": "According to the question, this consumer added the 15% tip on top of the bill and the tax.\nTherefore, you must first multiply $44.00 \u00d7 1.08 which equals $47.52. Now you will multiply\n$47.52 \u00d7 15% or 0.15. This results in $7.128 which rounds up to $7.13.", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 72, "excluded": false}, {"id": "AR-0193", "source_number": 193, "subtest": "AR", "stem": "Jane takes out a loan for $100,000.00 over 10 years and agrees to pay interest only at an\nannual rate of 8%.\nWhat will her monthly payment be?", "options": {"A": "$333.33", "B": "$666.67", "C": "$1,000", "D": "$8,000"}, "answer": "B", "answer_raw": "B", "explanation": "This question is asking you to only determine the monthly payment of an interest only loan.\nThus, you do not need to concern yourself with the 10-year term or the principal being repaid as\nthat is irrelevant. The only numbers you need to work with are the principal amount, the interest\nrate and the number of months in a year.\nThe formula for calculating an interest only loan would be (Principal \u00d7 Annual Rate) / Number of\nmonths in a year. Therefore:($100,000 \u00d7 0.08)/12 = $666.66666 or $666.67. A payment of\n$666.67 per month would result in payments of $8000.04 per year which is 8% of $100,000.00.", "figure": null, "passage_id": null, "topics": ["simple_interest", "percentages_discount"], "difficulty": 4, "flags": [], "page": 72, "excluded": false}, {"id": "AR-0194", "source_number": 194, "subtest": "AR", "stem": "Karen is 6 years older than her sister Michelle, and Michelle is 2 years younger than their\nbrother David.\nIf the sum of their ages is 62, how old is Michelle?", "options": {"A": "20", "B": "16", "C": "18", "D": "24"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 1, "flags": [], "page": 73, "excluded": false}, {"id": "AR-0195", "source_number": 195, "subtest": "AR", "stem": "A barista averages making 16 coffees per hour.\nAt this rate, how many hours will it take until she's made 1,200 coffees?", "options": {"A": "70 hours", "B": "75 hours", "C": "80 hours", "D": "65 hours"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 2, "flags": [], "page": 73, "excluded": false}, {"id": "AR-0196", "source_number": 196, "subtest": "AR", "stem": "Camille uses a 20% off coupon when buying a sweater that costs $47.99.\nIf she also pays 6% sales tax on the purchase, how much does she pay?", "options": {"A": "$50.87", "B": "$40.69", "C": "$38.39", "D": "$43.64"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 73, "excluded": false}, {"id": "AR-0197", "source_number": 197, "subtest": "AR", "stem": "At Michael's smoothie shop smoothies cost $3.50 during the week and $4.00 on weekends.\nIf Jonathan bought a smoothie every day except Saturday how much did he spend on\nsmoothies that week?", "options": {"A": "$21.50", "B": "$25.50", "C": "$17.50", "D": "$21.00"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 73, "excluded": false}, {"id": "AR-0198", "source_number": 198, "subtest": "AR", "stem": "In a classroom of 32 students, 14 are male.\nWhat percentage of the class is female?", "options": {"A": "56%", "B": "52%", "C": "44%", "D": "46%"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 73, "excluded": false}, {"id": "AR-0199", "source_number": 199, "subtest": "AR", "stem": "Cory's average score after 8 tests is 91%.\nIf he gets a 78% on his 9th test, what will his new average be?", "options": {"A": "90.5%", "B": "87.5%", "C": "89.6%", "D": "89.5%"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount", "averages"], "difficulty": 2, "flags": [], "page": 74, "excluded": false}, {"id": "AR-0200", "source_number": 200, "subtest": "AR", "stem": "Julie gives 7 pieces of candy to each of her friends.\nIf Julie gives all of her candy away, which amount of candy could have been the amount she\ndistributed?", "options": {"A": "128", "B": "161", "C": "145", "D": "162"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 2, "flags": [], "page": 74, "excluded": false}, {"id": "AR-0201", "source_number": 201, "subtest": "AR", "stem": "Four out of 28 students had to go to summer school.\nWhat is the ratio of students who did not have to go to summer school expressed, in its lowest\nterms?", "options": {"A": "4/5", "B": "7/8", "C": "9/10", "D": "6/7"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 1, "flags": [], "page": 74, "excluded": false}, {"id": "AR-0202", "source_number": 202, "subtest": "AR", "stem": "If doughnuts are usually 75 cents each, but there is a sale on Friday advertising them as 1\n\n\n\ndozen + 1/2 dozen for $10.80, what is the new cost for just one?", "options": {"A": "55 cents", "B": "50 cents", "C": "60 cents", "D": "65 cents"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 74, "excluded": false}, {"id": "AR-0203", "source_number": 203, "subtest": "AR", "stem": "A cross country coach just announced that, by the end of the quarter, all students should run the\n10 miles in less than 70 minutes.\nThere are 15 students in the group.\n6 of them ran 10 miles in 1 hour + 5 minutes\n4 of them ran 10 miles in 1 hour + 3 minutes\n2 of them ran 10 miles in 1 hour + 9 minutes\n3 of them ran 10 miles in 1 hour and 10 minutes.\nHow many students made the goal?", "options": {"A": "3", "B": "10", "C": "4", "D": "12"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 5, "flags": [], "page": 75, "excluded": false}, {"id": "AR-0204", "source_number": 204, "subtest": "AR", "stem": "You just went on a blind date and wanted to impress the girl by adding an 18% tip to the total\ncost of the meal. Two entrees came to a total of $35.90. Desserts cost $7.50 and beverages\ncost $6.60.\nWhat is the 18% tip going to cost?", "options": {"A": "$5.00", "B": "$7.75", "C": "$8.50", "D": "$9.00"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 3, "flags": [], "page": 75, "excluded": false}, {"id": "AR-0205", "source_number": 205, "subtest": "AR", "stem": "You are asked to buy bags of cement to pour a cement pad for a hot tub. You need to fill the\npad frame which has an 8-foot square base and one-foot high sides. Each bag of cement mixed\nwill fill 5 cubic feet in the frame.\nHow many bags will you need to buy to ensure enough to fill the entire frame?", "options": {"A": "8 bags", "B": "10 bags", "C": "13 bags", "D": "12 bags"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 4, "flags": [], "page": 75, "excluded": false}, {"id": "AR-0206", "source_number": 206, "subtest": "AR", "stem": "You are asked to chart the temperature during an 8-hour period to give the average.\nThese are your results:\n7am: -10 degrees\n8am: 0 degrees\n9 am: 30 degrees\n10 am: 36 degrees\n11 am: 40 degrees\n12 pm: 42 degrees\n1pm: 42 degrees\n2 pm: 41 degrees\nWhat is the average temperature?", "options": {"A": "about 32 degrees", "B": "about 40 degrees", "C": "about 28 degrees", "D": "about 30 degrees"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 4, "flags": [], "page": 76, "excluded": false}, {"id": "AR-0207", "source_number": 207, "subtest": "AR", "stem": "Your uncle passed away and left you and your siblings his private property. He owned a 180-\nacre ranch and there are 3 of you. Each acre is valued at approximately $3,000.\nThis means the monetary value for each sibling will be ___________.", "options": {"A": "$60,000", "B": "$18,000", "C": "$180,000", "D": "$54,000"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 76, "excluded": false}, {"id": "AR-0208", "source_number": 208, "subtest": "AR", "stem": "You are planning your vacation and trying to figure out the total number of miles you will be\ntraveling on a round trip from Portland, Oregon to Denver, Colorado, and back to Portland,\nOregon. The scale for the map you are consulting shows that 1 inch = 4 miles. Measuring, you\nfind that you will be traveling 3141/2 inches for the one- way trip.\nWhat is the total number of miles you will be traveling during the entire round trip?", "options": {"A": "314.5 miles", "B": "2,516 miles", "C": "1258 miles", "D": "629 miles"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 5, "flags": [], "page": 76, "excluded": false}, {"id": "AR-0209", "source_number": 209, "subtest": "AR", "stem": "Pete and his partner Mike made a huge profit in their software business together this year and\nhave decided to use $20,000 of the profit for a Christmas donation to their favorite charities.\nUsing the investment ratio each of them contributed to starting the business, Pete invested the\nmost with 4:1 ratio to Mike.\nHow much money will Mike get to donate to his charity?", "options": {"A": "$5,000", "B": "$4,000", "C": "$3,000", "D": "$16,000"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["ratio_proportion", "simple_interest", "cost_profit"], "difficulty": 4, "flags": [], "page": 77, "excluded": false}, {"id": "AR-0210", "source_number": 210, "subtest": "AR", "stem": "What is the sixth number in the series: 3, 6, 12, 24?", "options": {"A": "48", "B": "30", "C": "90", "D": "96"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 77, "excluded": false}, {"id": "AR-0211", "source_number": 211, "subtest": "AR", "stem": "At boarding school, students spend 1/4 of their time eating and sleeping, 3/5 of their time in\nclass, and 1/12 studying. The rest of the time is considered free time, which the student can\nspend doing activities of their own choosing.\nWhat fraction is considered free time?", "options": {"A": "1/15", "B": "1/20", "C": "1/10", "D": "1/12"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 77, "excluded": false}, {"id": "AR-0212", "source_number": 212, "subtest": "AR", "stem": "You just priced what it would cost to buy vinyl floor tiles at the local tile store. They quoted you\n$3.29 per tile. When you went home, you found the same tile for sale at an online outlet for\n$2.89 per tile.\nAs a percentage, how much more expensive is the tile store's quote?", "options": {"A": "The tile store's price costs about 14% more than the online outlet store.", "B": "The tile store's price costs about 11% more than the online outlet store.", "C": "The tile store's price costs about 16% more than the online outlet store.", "D": "The tile store's price costs about 10% more than the online outlet store."}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 5, "flags": [], "page": 77, "excluded": false}, {"id": "AR-0213", "source_number": 213, "subtest": "AR", "stem": "Susan went to the Spa and got a manicure for $25.00, a pedicure for $28.75 and a massage for\n$60.00. She tipped a total of $8.50.\nWhat is the total Susan spent at the Spa?", "options": {"A": "$113.75", "B": "$120.25", "C": "$122.25", "D": "$97.25"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 2, "flags": ["tag_fallback"], "page": 78, "excluded": false}, {"id": "AR-0214", "source_number": 214, "subtest": "AR", "stem": "Steve is mailing a small package. Postage rates are: $0.46 for the first ounce and $0.20 for\neach additional ounce. The UPS store is offering a special for $3.45 on a small box if your items\nfit, the weight not being a factor.\nWhich of the following weights would make it cheaper for Steve to ship his package by the post\noffice rather than by UPS?", "options": {"A": "18 ounces or higher", "B": "16 ounces", "C": "15 ounces", "D": "17 ounces"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 3, "flags": [], "page": 78, "excluded": false}, {"id": "AR-0215", "source_number": 215, "subtest": "AR", "stem": "Mike's motorcycle stalled at the beach and he called the towing company. They charged him\n$4.75 per mile for the first 25 miles and then $5.25 per mile for each mile over 25. Mike was 29\nmiles from the motorcycle repair shop.\nHow much was Mike's towing bill?", "options": {"A": "$139.75", "B": "$137.75", "C": "$118.75", "D": "$131.25"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 4, "flags": [], "page": 78, "excluded": false}, {"id": "AR-0216", "source_number": 216, "subtest": "AR", "stem": "The sum of two numbers is 84. One number is 6 more than the other.\nWhat is the smaller of the two numbers?", "options": {"A": "32", "B": "39", "C": "33", "D": "35"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["ratio_proportion", "averages"], "difficulty": 1, "flags": [], "page": 78, "excluded": false}, {"id": "AR-0217", "source_number": 217, "subtest": "AR", "stem": "The grocery store orders ibuprofen in bottles by the gross. The first day after stocking the\nshelves with a new shipment they sold 5 bottles. The next day they sold 8 and the third day 7.\nHow many bottles remain from the original order?", "options": {"A": "124", "B": "131", "C": "104", "D": "100"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 79, "excluded": false}, {"id": "AR-0218", "source_number": 218, "subtest": "AR", "stem": "Cindy's test scores on her first five finals were: 90, 92, 98, 96, and 94. In order for Cindy to keep\nher scholarship she needs to maintain a finals' average of 94 or higher.\nWhich of these scores on her sixth test (the final) will guarantee her average of 94 or higher?", "options": {"A": "89", "B": "90", "C": "96", "D": "88"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 4, "flags": [], "page": 79, "excluded": false}, {"id": "AR-0219", "source_number": 219, "subtest": "AR", "stem": "A waiter earns $11.00 an hour and approximately 10% of what he serves in a shift.\nIf he works a 6 hour shift and takes $425.00 in orders, his total earnings for the six hours would\nbe __________.", "options": {"A": "$66.00", "B": "$106.50", "C": "$42.50", "D": "$108.50"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 79, "excluded": false}, {"id": "AR-0220", "source_number": 220, "subtest": "AR", "stem": "How many square feet of tile is needed for a 24 foot \u00d7 24 foot room?", "options": {"A": "576 square feet", "B": "288 square feet", "C": "96 square feet", "D": "144 square feet"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 79, "excluded": false}, {"id": "AR-0221", "source_number": 221, "subtest": "AR", "stem": "John is going to waterproof his carpeting which is 18 feet \u00d7 24 feet. The rate is 57 cents per\nsquare foot to apply the waterproofing solution.\nJohn's total cost will be __________.", "options": {"A": "$244.24", "B": "$200.04", "C": "$246.24", "D": "$239.94"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["unit_conversion", "cost_profit"], "difficulty": 3, "flags": [], "page": 80, "excluded": false}, {"id": "AR-0222", "source_number": 222, "subtest": "AR", "stem": "A pen factory has a monthly overhead of $5,000. It costs them 21 cents to make a pen and they\nsell each pen for 99 cents.\nHow many pens will they need to sell each month in order to start making a profit?", "options": {"A": "5678", "B": "6411", "C": "7422", "D": "5416"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": [], "page": 80, "excluded": false}, {"id": "AR-0223", "source_number": 223, "subtest": "AR", "stem": "You are working in a hospital supply room and make $13.65 an hour. The union negotiates a\nnew contract giving each employee a 4.3% cost of living raise.\nWhat is your new hourly rate?", "options": {"A": "$14.59 an hour", "B": "$14.33 an hour", "C": "$14.24 an hour", "D": "$14.43 an hour"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 80, "excluded": false}, {"id": "AR-0224", "source_number": 224, "subtest": "AR", "stem": "You just left for vacation 2 hours ago. You have driven about 50 miles per hour on the 2-lane\nroad and take an exit to get dinner. You call your Dad to check in. Your Dad has decided to join\nyou after initially turning down your invitation.\n\n\n\nHow long will you have to wait for him if he drives 40 miles per hour?", "options": {"A": "2 hours + 30 minutes", "B": "2 hours + 40 minutes", "C": "3 hours", "D": "2 hours + 20 minutes"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 5, "flags": [], "page": 80, "excluded": false}, {"id": "AR-0225", "source_number": 225, "subtest": "AR", "stem": "A pizzeria caters parties and just finished baking 60 pizzas. The church youth group just picked\nup their order of 1/4 of the pizzas baked. A school graduation party is picking up 1/3 of the\npizzas baked. A martial arts club stopped in and bought 1/20 of the pizzas baked.\nHow many pizzas are left of the 60 that were baked?", "options": {"A": "20", "B": "18", "C": "15", "D": "22"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 5, "flags": ["tag_fallback"], "page": 81, "excluded": false}, {"id": "AR-0226", "source_number": 226, "subtest": "AR", "stem": "Jill bought 2 cases of computer paper (10 reams per case) on sale for $85.00. The regular rate\nis: 1 case = $52.50.\nWhat was her savings amount on the cost of each ream?", "options": {"A": "$1.00 per ream savings", "B": "$1.25 per ream savings", "C": "$0.75 per ream savings", "D": "$0.50 per ream savings"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 81, "excluded": false}, {"id": "AR-0227", "source_number": 227, "subtest": "AR", "stem": "You take your dog for a walk in the evenings and it takes about 25 minutes to walk 8 city blocks.\nIf you decide to do a \"marathon walk\" of 32 city blocks on a Saturday, how many minutes will it\ntake you to complete this?", "options": {"A": "1 hour + 40 minutes", "B": "1 hour + 25 minutes", "C": "1 hour", "D": "1 hour + 32 minutes"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 2, "flags": [], "page": 81, "excluded": false}, {"id": "AR-0228", "source_number": 228, "subtest": "AR", "stem": "School enrollments have fluctuated quite a bit in Oregon this year. The state department of\neducation predicted there would be 300,000 students enrolled state-wide. The enrollment ended\nup being 375,000.\nHow much of a percentage increase over the projected amount is this?", "options": {"A": "A 10% increase in the projected amount.", "B": "A 20% increase in the projected amount.", "C": "A 25% increase in the projected amount.", "D": "A 15% increase in the projected amount."}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 4, "flags": [], "page": 81, "excluded": false}, {"id": "AR-0229", "source_number": 229, "subtest": "AR", "stem": "You're applying for a job that has a skills test requirement. In order to pass you need to get 48\nof the 55 questions correct.\nWhat percent of the questions do you need to answer correctly?", "options": {"A": "87%", "B": "75%", "C": "55%", "D": "67%"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 82, "excluded": false}, {"id": "AR-0230", "source_number": 230, "subtest": "AR", "stem": "You just started a retirement fund by depositing $7,000 in an account. The annual interest rate\nfor an account with an \"early withdrawal\" penalty is 5.75%.\nHow much money will you have in your account if you leave it for 2 years?", "options": {"A": "$7402.50", "B": "$7080.50", "C": "$7500.28", "D": "$7828.14"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["simple_interest", "percentages_discount"], "difficulty": 3, "flags": [], "page": 82, "excluded": false}, {"id": "AR-0231", "source_number": 231, "subtest": "AR", "stem": "You're getting in shape for a marathon and are going to use the local school track to build up to\nmore mileage.\nThe track measures one quarter mile around.\nIf you ran 18 laps, how many miles would this be?", "options": {"A": "4 miles", "B": "3.50 miles", "C": "4.50 miles", "D": "3.75 miles"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 2, "flags": [], "page": 82, "excluded": false}, {"id": "AR-0232", "source_number": 232, "subtest": "AR", "stem": "You just drove 280 miles and it took you approximately 5 hours.\nHow many miles per hour was your average speed?", "options": {"A": "about 56 miles per hour", "B": "about 60 miles per hour", "C": "about 55 miles per hour", "D": "about 58 miles per hour"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate", "averages"], "difficulty": 2, "flags": [], "page": 83, "excluded": false}, {"id": "AR-0233", "source_number": 233, "subtest": "AR", "stem": "You work in a hospital and make $15.28 per hour for a 40 hour a week. If you work the night\nshift you get a slight differential added at $2.32 per hour worked during this shift. You just\ncompleted your first week and worked 34 hours on a regular shift and 6 hours on the night shift.\nWhat is the total amount you earned this week?", "options": {"A": "$519.52", "B": "$615.20", "C": "$611.20", "D": "$625.12"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["work_rate", "rate_time_distance"], "difficulty": 4, "flags": [], "page": 83, "excluded": false}, {"id": "AR-0234", "source_number": 234, "subtest": "AR", "stem": "Your local library branch has 28 employees and currently provides approximately 48 square feet\nper employee for a work station. The library just hired 2 new employees.\nTo make room to add these 2 new people, each employee's work station will be reduced to\nabout:", "options": {"A": "28.8 square feet", "B": "44.8 square feet", "C": "42.8 square feet", "D": "30.8 square feet"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["unit_conversion", "ratio_proportion", "percentages_discount"], "difficulty": 2, "flags": [], "page": 83, "excluded": false}, {"id": "AR-0235", "source_number": 235, "subtest": "AR", "stem": "Tom has been saving for a new car and finally has the money to make the deal. He put down\n$3,800 and will be paying $325 a month for 5.5 years.\nWhat is the total cost of his purchase?", "options": {"A": "$19,500", "B": "$21,450", "C": "$25,250", "D": "$23,300"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["percentages_discount", "cost_profit"], "difficulty": 3, "flags": [], "page": 83, "excluded": false}, {"id": "AR-0236", "source_number": 236, "subtest": "AR", "stem": "Eight girls in a club are comparing their weekly allowance. Jan and Sue each receive $10 a\nweek. Lori and Tina each receive $5 a week. Julie, Christie and Faith each receive $12 a week.\nCheryl does not get an allowance but her parents often buy her things as she needs them.\nWhat is the average amount of allowance given among these 8 girls?", "options": {"A": "$7.00", "B": "$8.25", "C": "$9.42", "D": "$6.75"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["averages"], "difficulty": 3, "flags": [], "page": 84, "excluded": false}, {"id": "AR-0237", "source_number": 237, "subtest": "AR", "stem": "The distance between cities A and B is approximately 1,800 miles.\nIf you drive an average of 55 miles per hour, how many hours will it take you to drive from city A\nto city B?", "options": {"A": "approximately 22 hours", "B": "approximately 24 hours", "C": "approximately 36 hours", "D": "approximately 33 hours"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate", "averages"], "difficulty": 3, "flags": [], "page": 84, "excluded": false}, {"id": "AR-0238", "source_number": 238, "subtest": "AR", "stem": "You are hosting a graduation party and you need 32 gallons of lemonade.\nWhich is the best buy?", "options": {"A": "three 10-gallon jugs at $208 each + two 1-gallon jugs at $15 each", "B": "one 25-gallon jug at $542 + one 5-gallon jug at $100 + two 1-gallon jugs at $15 each", "C": "one 25-gallon jug at $542 + one 10-gallon jug at $208", "D": "six 5-gallon jugs at $100 each + two 1-gallon jugs at $15 each"}, "answer": "D", "answer_raw": "D", "explanation": "", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 2, "flags": [], "page": 84, "excluded": false}, {"id": "AR-0239", "source_number": 239, "subtest": "AR", "stem": "Chris is driving a truck that can hold 4 tons maximum. He has a shipment of food weighing\n26,000 pounds.\nHow many trips will he need to make to deliver all of the food?", "options": {"A": "1 trip", "B": "3 trips", "C": "4 trips", "D": "2 trips"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance"], "difficulty": 2, "flags": [], "page": 84, "excluded": false}, {"id": "AR-0240", "source_number": 240, "subtest": "AR", "stem": "Two monorails depart their respective stations at the same time. The monorail headed south is\ntraveling 65 miles an hour, while the monorail headed north is traveling 55 miles per hour.\nGiven this information, how many miles will both monorails travel in 4 hours?", "options": {"A": "480 miles", "B": "465 miles", "C": "570 miles", "D": "508 miles"}, "answer": "A", "answer_raw": "A", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 4, "flags": [], "page": 85, "excluded": false}, {"id": "AR-0241", "source_number": 241, "subtest": "AR", "stem": "Your new remodel is almost done. The contractor needs to put the final framing on and needs 8\nsections, measuring 4 feet, 2 inches each. The framing is available from the supplier by 10-foot\nlengths only.\nWhat is the total length of the lumber that needs to be purchased?", "options": {"A": "34 feet", "B": "40 feet", "C": "48 feet", "D": "30 feet"}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 85, "excluded": false}, {"id": "AR-0242", "source_number": 242, "subtest": "AR", "stem": "You just bought 4 take-out Mexican dinners. They were priced $14.96, $14.96, $15.75, and\n$17.85. You had a coupon to \"buy one, get a second one for half-price on all items that are the\nsame price.\" (Only 1 coupon per purchase allowed).\nWhat is the total amount you paid?", "options": {"A": "$55.25", "B": "$58.04", "C": "$56.04", "D": "$63.52"}, "answer": "C", "answer_raw": "C", "explanation": "", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 4, "flags": ["tag_fallback"], "page": 85, "excluded": false}, {"id": "AR-0243", "source_number": 243, "subtest": "AR", "stem": "Bob just got hired for on-the-road sales and will travel about 1,500 miles a week during a 40-\nhour work week.\nIf the time spent traveling is 2/3 of his week, how many hours a week will he be on the road?", "options": {"A": "Bob spends about 20 hours of his 40-hour work week on the road.", "B": "Bob spends about 27 hours of his 40-hour work week on the road.", "C": "Bob spends about 22 hours of his 40-hour workweek on the road.", "D": "Bob spends about 13 hours of his 40-hour work week on the road."}, "answer": "B", "answer_raw": "B", "explanation": "", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 5, "flags": [], "page": 85, "excluded": false}, {"id": "AR-0244", "source_number": 244, "subtest": "AR", "stem": "If you invest $10,000 at an annual rate of 7%, how much interest will you earn after one year?", "options": {"A": "$7", "B": "$700", "C": "$10,700", "D": "$70"}, "answer": "B", "answer_raw": "B", "explanation": "Interest = Principal \u00d7 Rate = $10,000 \u00d7 0.07 = $700", "figure": null, "passage_id": null, "topics": ["simple_interest", "percentages_discount"], "difficulty": 2, "flags": [], "page": 86, "excluded": false}, {"id": "AR-0245", "source_number": 245, "subtest": "AR", "stem": "How many pounds does four tons of gravel weigh?", "options": {"A": "4000", "B": "16000", "C": "8000", "D": "12000"}, "answer": "C", "answer_raw": "C", "explanation": "One ton = 2,000 pounds. Therefore, 4 tons = 8,000 pounds", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 86, "excluded": false}, {"id": "AR-0246", "source_number": 246, "subtest": "AR", "stem": "If the price of a gallon of gas increases from $3.20 to $3.68, what percent did it increase?", "options": {"A": "15%", "B": "10%", "C": "115%", "D": "12%"}, "answer": "A", "answer_raw": "A", "explanation": "To find the percent of increase, subtract the second number from the original/first number (3.68\n- 3.2 = 0.48) and divide that result by the original number (0.48 / 3.20 = 0.15 = 15%)", "figure": null, "passage_id": null, "topics": ["percentages_discount", "unit_conversion"], "difficulty": 2, "flags": [], "page": 86, "excluded": false}, {"id": "AR-0247", "source_number": 247, "subtest": "AR", "stem": "If 5 apples cost $2.00, how much will 15 apples cost?", "options": {"A": "$8", "B": "$30", "C": "$10", "D": "$6"}, "answer": "D", "answer_raw": "D", "explanation": "15 apples are three times as many as 5 apples, so 15 apples will cost 3 \u00d7 $2 = $6", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": [], "page": 87, "excluded": false}, {"id": "AR-0248", "source_number": 248, "subtest": "AR", "stem": "If 4 people can stain a deck in 2 days, how many people would be required to stain the deck in\nonly 1 day?", "options": {"A": "8", "B": "2", "C": "4", "D": "12"}, "answer": "A", "answer_raw": "A", "explanation": "If it requires 4 people for 2 days, then it would require 8 people for 1 day.", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 87, "excluded": false}, {"id": "AR-0249", "source_number": 249, "subtest": "AR", "stem": "How much time is there between 7:45 am today and 3:15 pm tomorrow?", "options": {"A": "71/2 hours", "B": "301/2 hours", "C": "311/2 hours", "D": "321/2 hours"}, "answer": "C", "answer_raw": "C", "explanation": "From 7:45 am today to 7:45 am tomorrow is 24 hours. From 7:45 am tomorrow to 3:15 pm\ntomorrow is 71/2 hours. Total is 311/2 hours.", "figure": null, "passage_id": null, "topics": ["ratio_proportion"], "difficulty": 1, "flags": [], "page": 87, "excluded": false}, {"id": "AR-0250", "source_number": 250, "subtest": "AR", "stem": "If a gas tank can hold 30 gallons, how many gallons does it contain when it is three-fifths full?", "options": {"A": "15", "B": "12", "C": "24", "D": "18"}, "answer": "D", "answer_raw": "D", "explanation": "30 gallons \u00d7 3/5 = 18", "figure": null, "passage_id": null, "topics": ["unit_conversion"], "difficulty": 1, "flags": [], "page": 87, "excluded": false}, {"id": "AR-0251", "source_number": 251, "subtest": "AR", "stem": "How long will it take to reach a town 250 miles away if you drive 50 miles per hour?", "options": {"A": "4 hours", "B": "5 hours", "C": "10 hours", "D": "6 hours"}, "answer": "B", "answer_raw": "B", "explanation": "250 miles/(50 miles per hour) = 5 hours", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "work_rate"], "difficulty": 2, "flags": [], "page": 88, "excluded": false}, {"id": "AR-0252", "source_number": 252, "subtest": "AR", "stem": "Tina bought a scarf for $16.65. She gave the clerk $20.\nHow much change should she get back?", "options": {"A": "$4.35", "B": "$3.45", "C": "$3.35", "D": "$3.25"}, "answer": "C", "answer_raw": "C", "explanation": "$20 - $16.65 = $3.35", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 88, "excluded": false}, {"id": "AR-0253", "source_number": 253, "subtest": "AR", "stem": "Sam bought a 12 pack of soda for $5.40.\nHow much did he pay per can of soda?", "options": {"A": "$0.45", "B": "$0.54", "C": "$0.40", "D": "$2.22"}, "answer": "A", "answer_raw": "A", "explanation": "$5.40/12 = $0.45", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 1, "flags": ["tag_fallback"], "page": 88, "excluded": false}, {"id": "AR-0254", "source_number": 254, "subtest": "AR", "stem": "A stack of bricks is 3 1/2 feet high.\nIf each brick is 13/4 inches high, how many bricks are in the stack?", "options": {"A": "2", "B": "12", "C": "24", "D": "28"}, "answer": "C", "answer_raw": "C", "explanation": "31/2 feet \u00d7 12 in/ft = 42 inches.\n42 inches/1.75 inches = 24 bricks", "figure": null, "passage_id": null, "topics": ["cost_profit"], "difficulty": 3, "flags": ["tag_fallback"], "page": 89, "excluded": false}, {"id": "AR-0255", "source_number": 255, "subtest": "AR", "stem": "A book regularly sells for $28.\nIf the book is on sale for \"20% off\", how much is the sales price of the book?", "options": {"A": "$5.60", "B": "$25.20", "C": "$21.20", "D": "$22.40"}, "answer": "D", "answer_raw": "D", "explanation": "20% of $28 = 28 \u00d7 0.2 = $5.60.\nThe sales price is then $28 - $5.6 = $22.40", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 1, "flags": [], "page": 89, "excluded": false}, {"id": "AR-0256", "source_number": 256, "subtest": "AR", "stem": "A scale on a map says that 1 inch represents 60 miles.\nIf the distance between two points on the map is 21/2 inches, how many miles are between the\ntwo points?", "options": {"A": "150", "B": "120", "C": "24", "D": "180"}, "answer": "A", "answer_raw": "A", "explanation": "21/2 \u00d7 60 = 150", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "ratio_proportion"], "difficulty": 2, "flags": [], "page": 89, "excluded": false}, {"id": "AR-0257", "source_number": 257, "subtest": "AR", "stem": "A car has a 15-gallon gas tank.\nIf a car gets 32 miles per gallon and travels 384 miles, how much gas will be left in the tank?", "options": {"A": "12", "B": "6", "C": "3", "D": "4"}, "answer": "C", "answer_raw": "C", "explanation": "The car will have used 12 gallons (384 miles / 32 gallons). Therefore, there will be 3 gallons left\nin the tank (15 gallons - 3 gallons).", "figure": null, "passage_id": null, "topics": ["rate_time_distance", "unit_conversion"], "difficulty": 2, "flags": [], "page": 89, "excluded": false}, {"id": "AR-0258", "source_number": 258, "subtest": "AR", "stem": "A man's hourly wage increased from $12.50 to $13.50.\nWhat percent raise did he get?", "options": {"A": "10%", "B": "13.50%", "C": "9%", "D": "8%"}, "answer": "D", "answer_raw": "D", "explanation": "To find the percent of increase, subtract the second number from the original/first number (13.5\n- 12.5 = 1.0) and divide that result by the original number (1 / 12.5 = 0.08 = 8%).\n\n\n\nSection 2: Auto and Shop Information", "figure": null, "passage_id": null, "topics": ["percentages_discount"], "difficulty": 2, "flags": [], "page": 90, "excluded": false}];
})(typeof self !== "undefined" ? self : this);
